import React, { useState } from 'react';
import { X, Wand2, Loader2, Link as LinkIcon } from 'lucide-react';
import { generateMovieMetadata } from '../services/geminiService';
import { Movie } from '../types';

interface AddMovieModalProps {
  onClose: () => void;
  onAdd: (movie: Movie) => void;
}

export const AddMovieModal: React.FC<AddMovieModalProps> = ({ onClose, onAdd }) => {
  const [title, setTitle] = useState('');
  const [streamUrl, setStreamUrl] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSmartGenerate = async () => {
    if (!title) return;
    setLoading(true);
    setError('');

    try {
      const metadata = await generateMovieMetadata(title);

      const newMovie: Movie = {
        id: crypto.randomUUID(),
        title: title,
        streamUrl: streamUrl || 'https://www.youtube.com/embed/dQw4w9WgXcQ', // Default fallback if empty
        posterUrl: `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`, // Dynamic placeholder
        ...metadata
      };

      onAdd(newMovie);
      onClose();
    } catch (e) {
      setError("Error al generar datos. Intenta nuevamente.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center px-4">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={onClose} />

      {/* Modal */}
      <div className="relative bg-brand-800 rounded-2xl w-full max-w-lg border border-white/10 shadow-2xl overflow-hidden">
        <div className="p-6 border-b border-white/10 flex justify-between items-center">
          <h2 className="text-xl font-bold text-white flex items-center">
            <Wand2 className="h-5 w-5 mr-2 text-brand-500" />
            Agregar Película con IA
          </h2>
          <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors">
            <X className="h-6 w-6" />
          </button>
        </div>

        <div className="p-6 space-y-6">

          {/* Note for User */}
          <div className="bg-blue-900/20 border border-blue-500/20 rounded-lg p-4">
            <p className="text-xs text-blue-200">
              <span className="font-bold block mb-1">Nota Importante:</span>
              Ingresa el título para que Gemini IA genere la portada y descripción. Pega el link de la película (embed/iframe) para verla.
            </p>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">Título de la Película</label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full bg-brand-900 border border-white/10 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-brand-500 focus:border-transparent outline-none transition-all"
              placeholder="Ej: Avatar: Fire and Ash"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">Link de Streaming (Embed/Iframe)</label>
            <div className="relative">
              <LinkIcon className="absolute left-3 top-3.5 h-5 w-5 text-gray-500" />
              <input
                type="text"
                value={streamUrl}
                onChange={(e) => setStreamUrl(e.target.value)}
                className="w-full bg-brand-900 border border-white/10 rounded-lg pl-10 pr-4 py-3 text-white focus:ring-2 focus:ring-brand-500 focus:border-transparent outline-none transition-all"
                placeholder="https://servidor.com/embed/..."
              />
            </div>
          </div>

          {error && <p className="text-red-400 text-sm">{error}</p>}

          <button
            onClick={handleSmartGenerate}
            disabled={!title || loading}
            className={`w-full py-3 rounded-lg font-bold text-white shadow-lg flex items-center justify-center transition-all ${
              !title || loading 
                ? 'bg-gray-600 cursor-not-allowed' 
                : 'bg-gradient-to-r from-brand-500 to-blue-600 hover:from-blue-600 hover:to-blue-700 hover:shadow-brand-500/25'
            }`}
          >
            {loading ? (
              <>
                <Loader2 className="animate-spin h-5 w-5 mr-2" />
                Consultando a Gemini...
              </>
            ) : (
              'Generar y Agregar'
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ArrowLeft, AlertTriangle, Maximize2 } from 'lucide-react';
import { Movie } from '../types';

interface PlayerProps {
  movie: Movie;
  onBack: () => void;
}

export const Player: React.FC<PlayerProps> = ({ movie, onBack }) => {
  const [iframeError, setIframeError] = useState(false);

  // Helper to ensure url can be embedded roughly (basic check)
  const getEmbedUrl = (url: string) => {
    // If it's a direct youtube link, try to convert to embed
    if (url.includes('youtube.com/watch?v=')) {
      return url.replace('watch?v=', 'embed/');
    }
    return url;
  };

  return (
    <div className="fixed inset-0 z-[60] bg-black flex flex-col">
      {/* Player Header */}
      <div className="absolute top-0 left-0 right-0 p-4 bg-gradient-to-b from-black/80 to-transparent z-10 flex justify-between items-center pointer-events-none">
        <button 
          onClick={onBack}
          className="pointer-events-auto flex items-center px-4 py-2 bg-white/10 backdrop-blur-md hover:bg-white/20 rounded-full text-white transition-all group"
        >
          <ArrowLeft className="h-5 w-5 mr-2 group-hover:-translate-x-1 transition-transform" />
          Volver
        </button>
        <h1 className="text-white font-bold text-lg drop-shadow-md hidden sm:block">{movie.title}</h1>
      </div>

      {/* Main Player Container */}
      <div className="flex-1 w-full h-full relative bg-black flex items-center justify-center">
        {!iframeError ? (
            <iframe
            src={getEmbedUrl(movie.streamUrl)}
            className="w-full h-full border-0"
            allowFullScreen
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
            onError={() => setIframeError(true)}
            title={`Reproductor de ${movie.title}`}
            referrerPolicy="no-referrer" // Helps with some streaming sites
            sandbox="allow-forms allow-pointer-lock allow-same-origin allow-scripts allow-top-navigation"
          />
        ) : (
          <div className="text-center p-8 max-w-lg">
            <AlertTriangle className="h-16 w-16 text-yellow-500 mx-auto mb-4" />
            <h3 className="text-2xl font-bold text-white mb-2">No se pudo cargar el video</h3>
            <p className="text-gray-400 mb-6">
              El servidor externo rechazó la conexión o el link no es un embed válido.
            </p>
            <a 
              href={movie.streamUrl} 
              target="_blank" 
              rel="noreferrer"
              className="inline-flex items-center px-6 py-3 bg-brand-500 hover:bg-brand-600 text-white font-bold rounded-lg transition-colors"
            >
              Abrir en nueva pestaña <Maximize2 className="ml-2 h-4 w-4" />
            </a>
          </div>
        )}
      </div>

      {/* Info Bar */}
      <div className="bg-brand-900 border-t border-white/10 p-6">
         <div className="max-w-7xl mx-auto">
            <div className="flex flex-col md:flex-row md:items-start justify-between gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-white mb-2">{movie.title} <span className="text-gray-500 text-lg font-normal">({movie.year})</span></h2>
                    <p className="text-gray-300 max-w-3xl leading-relaxed">{movie.description}</p>
                    <div className="flex gap-2 mt-4">
                        {movie.genre.map(g => (
                            <span key={g} className="px-3 py-1 bg-white/5 border border-white/10 rounded-full text-xs text-gray-300">
                                {g}
                            </span>
                        ))}
                    </div>
                </div>
                <div className="flex-shrink-0">
                    <div className="flex items-center space-x-2 bg-brand-800 px-4 py-2 rounded-lg border border-white/10">
                        <span className="text-yellow-400 text-xl font-bold">{movie.rating}</span>
                        <span className="text-gray-500 text-xs uppercase tracking-wider">IMDB Score</span>
                    </div>
                </div>
            </div>
         </div>
      </div>
    </div>
  );
};

