import React, { useState, useEffect } from 'react';
import { ArrowLeft, ExternalLink, MonitorPlay, Server, RefreshCw } from 'lucide-react';
import { Movie } from '../types';

interface PlayerProps {
  movie: Movie;
  onBack: () => void;
}

export const Player: React.FC<PlayerProps> = ({ movie, onBack }) => {
  const [iframeError, setIframeError] = useState(false);
  const [currentServer, setCurrentServer] = useState(0);
  const [isLoading, setIsLoading] = useState(true);

  // List of reliable public embed servers
  // Only used if the movie has an IMDB ID
  const SERVERS = movie.imdbId ? [
    { name: "Servidor Principal (HD)", url: `https://embed.su/embed/movie/${movie.imdbId}` },
    { name: "Servidor Alternativo 1", url: `https://vidsrc.to/embed/movie/${movie.imdbId}` },
    { name: "Servidor Alternativo 2", url: `https://vidsrc.xyz/embed/movie/${movie.imdbId}` },
    { name: "Servidor Clásico", url: `https://www.2embed.cc/embed/${movie.imdbId}` },
  ] : [
    { name: "Enlace Personalizado", url: movie.streamUrl }
  ];

  const activeUrl = SERVERS[currentServer].url;

  useEffect(() => {
    // Reset state when server changes
    setIframeError(false);
    setIsLoading(true);
  }, [currentServer]);

  const handleIframeLoad = () => {
    setIsLoading(false);
  };

  const openCinemaMode = () => {
    const width = 1024;
    const height = 768;
    const left = (window.screen.width - width) / 2;
    const top = (window.screen.height - height) / 2;

    window.open(
      activeUrl,
      `CinemaMode-${movie.id}`,
      `toolbar=no,location=no,status=no,menubar=no,scrollbars=yes,resizable=yes,width=${width},height=${height},top=${top},left=${left}`
    );
  };

  return (
    <div className="fixed inset-0 z-[60] bg-black flex flex-col">
      {/* Player Header */}
      <div className="absolute top-0 left-0 right-0 p-4 bg-gradient-to-b from-black/90 to-transparent z-20 flex justify-between items-center pointer-events-none">
        <button 
          onClick={onBack}
          className="pointer-events-auto flex items-center px-4 py-2 bg-white/10 backdrop-blur-md hover:bg-white/20 rounded-full text-white transition-all group border border-white/5"
        >
          <ArrowLeft className="h-5 w-5 mr-2 group-hover:-translate-x-1 transition-transform" />
          Volver
        </button>
        <h1 className="text-white font-bold text-lg drop-shadow-md hidden sm:block opacity-80">{movie.title}</h1>
      </div>

      {/* Server Selector (If IMDB ID exists) */}
      {movie.imdbId && (
        <div className="absolute top-20 right-4 z-30 flex flex-col items-end gap-2">
            <div className="bg-black/80 backdrop-blur-md p-2 rounded-lg border border-white/10 text-xs text-gray-400 mb-1">
                <span className="flex items-center gap-1"><Server className="h-3 w-3" /> Fuentes de Video</span>
            </div>
            {SERVERS.map((server, index) => (
                <button
                    key={index}
                    onClick={() => setCurrentServer(index)}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition-all shadow-lg backdrop-blur-sm border ${
                        currentServer === index 
                        ? 'bg-brand-500 text-white border-brand-400' 
                        : 'bg-black/60 text-gray-300 border-white/10 hover:bg-white/10'
                    }`}
                >
                    {server.name}
                </button>
            ))}
        </div>
      )}

      {/* Main Player Container */}
      <div className="flex-1 w-full h-full relative bg-black flex items-center justify-center overflow-hidden">

        {/* Loading Spinner */}
        {isLoading && !iframeError && (
            <div className="absolute inset-0 flex items-center justify-center bg-black z-0">
                <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-brand-500"></div>
            </div>
        )}

        {/* Helper overlay for blocked connections */}
        <div className="absolute bottom-8 left-8 z-30 pointer-events-auto">
             <button 
                onClick={openCinemaMode}
                className="flex items-center gap-2 px-6 py-3 bg-white/10 hover:bg-white/20 backdrop-blur-md text-white rounded-xl transition-all border border-white/10 group"
             >
                <MonitorPlay className="h-5 w-5 text-brand-400 group-hover:scale-110 transition-transform" />
                <span className="text-sm font-medium">Abrir en Ventana Flotante (Modo Cine)</span>
             </button>
        </div>

        {!iframeError ? (
            <iframe
            key={activeUrl} // Force re-render on url change
            src={activeUrl}
            className="w-full h-full border-0 relative z-10"
            allowFullScreen
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
            onError={() => setIframeError(true)}
            onLoad={handleIframeLoad}
            title={`Reproductor de ${movie.title}`}
            referrerPolicy="no-referrer"
            sandbox="allow-forms allow-pointer-lock allow-same-origin allow-scripts allow-popups"
          />
        ) : (
          <div className="text-center p-8 max-w-lg relative z-10">
            <RefreshCw className="h-16 w-16 text-red-500 mx-auto mb-4" />
            <h3 className="text-2xl font-bold text-white mb-3">Error en el Servidor</h3>
            <p className="text-gray-300 mb-6">
              El servidor actual no responde. Intenta seleccionar otro servidor de la lista de la derecha.
            </p>
            <div className="flex justify-center gap-4">
                {SERVERS.map((server, index) => (
                    index !== currentServer && (
                        <button 
                            key={index}
                            onClick={() => setCurrentServer(index)}
                            className="px-4 py-2 bg-brand-800 hover:bg-brand-700 rounded text-sm text-white border border-white/10"
                        >
                            Probar {server.name}
                        </button>
                    )
                ))}
            </div>
          </div>
        )}
      </div>

      {/* Info Bar */}
      <div className="bg-brand-900 border-t border-white/10 p-6 z-20">
         <div className="max-w-7xl mx-auto">
            <div className="flex flex-col md:flex-row md:items-start justify-between gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-white mb-2">{movie.title} <span className="text-gray-500 text-lg font-normal">({movie.year})</span></h2>
                    <p className="text-gray-300 max-w-3xl leading-relaxed">{movie.description}</p>
                    <div className="flex gap-2 mt-4">
                        {movie.genre.map(g => (
                            <span key={g} className="px-3 py-1 bg-white/5 border border-white/10 rounded-full text-xs text-gray-300">
                                {g}
                            </span>
                        ))}
                    </div>
                </div>
                <div className="flex-shrink-0">
                    <div className="flex items-center space-x-2 bg-brand-800 px-4 py-2 rounded-lg border border-white/10">
                        <span className="text-yellow-400 text-xl font-bold">{movie.rating}</span>
                        <span className="text-gray-500 text-xs uppercase tracking-wider">IMDB Score</span>
                    </div>
                </div>
            </div>
         </div>
      </div>
    </div>
  );
};

