  const normalizeUrl = (url: string) => {
    if (!url) return '';
    // Fix Archive.org links: details pages block iframes, embed pages work.
    if (url.includes('archive.org/details/')) {
        return url.replace('/details/', '/embed/');
    }
    return url;
  };

  const SERVERS = movie.imdbId ? [
    { name: "VidSrc.to (Muy Estable)", url: `https://vidsrc.to/embed/movie/${movie.imdbId}` },
    { name: "Embed.su (HD Multi)", url: `https://embed.su/embed/movie/${movie.imdbId}` },
    { name: "SuperEmbed", url: `https://superembed.stream/embed/movie/${movie.imdbId}` },
    { name: "VidSrc.xyz", url: `https://vidsrc.xyz/embed/movie/${movie.imdbId}` },
    { name: "SmashyStream", url: `https://embed.smashystream.com/playere.php?tmdb=${movie.imdbId}` },
    { name: "2Embed", url: `https://www.2embed.cc/embed/${movie.imdbId}` },
  ] : [
    { name: "Enlace Personalizado", url: normalizeUrl(movie.streamUrl) }
  ];

  const activeUrl = SERVERS[currentServer].url;

  useEffect(() => {
    setIframeError(false);
    setIsLoading(true);
  }, [currentServer]);

  const handleIframeLoad = () => {
    setIsLoading(false);
  };

  const openExternal = () => {
    window.open(activeUrl, '_blank');
  };

