    const query = `ver pelicula "${movie.title}" completa online gratis iframe`;
    window.open(`https://www.google.com/search?q=${encodeURIComponent(query)}`, '_blank');
  };

  const handleManualSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (manualUrl) {
        const fixedUrl = normalizeUrl(manualUrl);
        const win = window.open(fixedUrl, '_blank');
        if (win) win.focus();
    }
  };

  return (
    <div className="fixed inset-0 z-[60] bg-black flex flex-col">
      {/* Player Header */}
      <div className="absolute top-0 left-0 right-0 p-4 bg-gradient-to-b from-black/90 to-transparent z-20 flex justify-between items-center pointer-events-none">
