          className="pointer-events-auto flex items-center px-4 py-2 bg-white/10 backdrop-blur-md hover:bg-white/20 rounded-full text-white transition-all group border border-white/5"
        >
          <ArrowLeft className="h-5 w-5 mr-2 group-hover:-translate-x-1 transition-transform" />
          Volver
