                    </button>
                </div>
                )}
            </div>
          </main>

          {/* Modal */}
          {isModalOpen && (
            <AddMovieModal 
              onClose={() => setIsModalOpen(false)} 
              onAdd={handleAddMovie} 
            />
          )}
        </>
      )}
    </div>
  );
};

