import React, { useState } from 'react';
import { X, Wand2, Loader2, Link as LinkIcon, Info, CheckCircle } from 'lucide-react';
import { generateMovieMetadata } from '../services/geminiService';
import { Movie } from '../types';

interface AddMovieModalProps {
  onClose: () => void;
  onAdd: (movie: Movie) => void;
}

export const AddMovieModal: React.FC<AddMovieModalProps> = ({ onClose, onAdd }) => {
  const [title, setTitle] = useState('');
  const [streamUrl, setStreamUrl] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [autoMode, setAutoMode] = useState(true);

  const handleSmartGenerate = async () => {
    if (!title) {
        setError("Por favor escribe el título de la película.");
        return;
    }
    setLoading(true);
    setError('');

    try {
      const metadata = await generateMovieMetadata(title);

      let finalStreamUrl = streamUrl;

      if (!finalStreamUrl) {
         finalStreamUrl = 'https://google.com/search?q=' + encodeURIComponent(title + ' movie watch online');
      }

      const newMovie: Movie = {
        id: crypto.randomUUID(),
        title: title,
        streamUrl: finalStreamUrl,
        posterUrl: `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`,
        ...metadata
      };

      onAdd(newMovie);
      onClose();
    } catch (e) {
      setError("Error al generar datos. Intenta nuevamente.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center px-4 py-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={onClose} />

      <div className="relative bg-[#1a1c22] rounded-2xl w-full max-w-lg border border-white/10 shadow-2xl flex flex-col max-h-[90vh]">
        <div className="p-5 border-b border-white/10 flex justify-between items-center shrink-0">
          <h2 className="text-xl font-bold text-white flex items-center">
            <Wand2 className="h-5 w-5 mr-2 text-brand-500" />
            Agregar al Catálogo
          </h2>
          <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors">
            <X className="h-6 w-6" />
          </button>
        </div>

        <div className="p-5 space-y-5 overflow-y-auto custom-scrollbar">

          <div className="bg-brand-900/50 border border-brand-500/30 rounded-lg p-4">
            <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-bold text-white">Modo Automático</span>
                <button 
                    onClick={() => setAutoMode(!autoMode)}
                    className={`w-10 h-6 rounded-full p-1 transition-colors ${autoMode ? 'bg-brand-500' : 'bg-gray-600'}`}
                >
                    <div className={`w-4 h-4 bg-white rounded-full shadow-md transform transition-transform ${autoMode ? 'translate-x-4' : ''}`} />
                </button>
            </div>
            <p className="text-xs text-gray-400">
                {autoMode 
                    ? "Escribe el título. La IA generará la descripción y carátula. Si no pones link, se generará una búsqueda de Google." 
                    : "Ingresa los datos manualmente."}
            </p>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">Título de la Película</label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full bg-[#0f1014] border border-white/10 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-brand-500 focus:border-transparent outline-none transition-all"
              placeholder="Ej: Avatar: Fire and Ash"
            />
          </div>

          {!autoMode && (
              <div>
                <label className="block text-sm font-medium text-gray-300 mb-2">Link Página Web Original</label>
                <div className="relative">
                  <LinkIcon className="absolute left-3 top-3.5 h-5 w-5 text-gray-500" />
                  <input
                    type="text"
                    value={streamUrl}
                    onChange={(e) => setStreamUrl(e.target.value)}
                    className="w-full bg-[#0f1014] border border-white/10 rounded-lg pl-10 pr-4 py-3 text-white focus:ring-2 focus:ring-brand-500 focus:border-transparent outline-none transition-all"
                    placeholder="https://pagina-de-peliculas.com/ver/..."
                  />
                </div>
                <p className="text-xs text-gray-500 mt-1">
                    El link a donde será redirigido el usuario.
                </p>
              </div>
          )}

          {error && <p className="text-red-400 text-sm">{error}</p>}

          <button
            onClick={handleSmartGenerate}
            disabled={!title || loading}
            className={`w-full py-3 rounded-lg font-bold text-white shadow-lg flex items-center justify-center transition-all ${
              !title || loading 
                ? 'bg-gray-600 cursor-not-allowed' 
                : 'bg-gradient-to-r from-brand-500 to-blue-600 hover:from-blue-600 hover:to-blue-700 hover:shadow-brand-500/25'
            }`}
          >
            {loading ? (
              <>
                <Loader2 className="animate-spin h-5 w-5 mr-2" />
                Generando Ficha...
              </>
            ) : (
              autoMode ? '✨ Generar Ficha Automática' : 'Agregar Película'
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

