const App: React.FC = () => {
  const [movies, setMovies] = useState<Movie[]>(INITIAL_MOVIES);
  const [viewState, setViewState] = useState<ViewState>(ViewState.HOME);
  const [currentMovie, setCurrentMovie] = useState<Movie | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);

  const filteredMovies = useMemo(() => {
    return movies.filter(m => 
      m.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
      m.genre.some(g => g.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [movies, searchTerm]);

  // Derived Trending List: Prioritize specific movies to match the design request
  const trendingMovies = useMemo(() => {
    if (searchTerm) return []; // Hide trends when searching

    const priorityTitles = ["Stranger Things", "Gran Diluvio", "Welcome to Derry", "Zootopia 2", "Conjuring"];
    const trends: Movie[] = [];
    const others: Movie[] = [];

    // Separate priority movies
    movies.forEach(m => {
        if (priorityTitles.some(pt => m.title.includes(pt))) {
            trends.push(m);
        } else {
            others.push(m);
        }
    });

    // Sort priority movies based on priorityTitles index
    trends.sort((a, b) => {
        const indexA = priorityTitles.findIndex(pt => a.title.includes(pt));
        const indexB = priorityTitles.findIndex(pt => b.title.includes(pt));
        return indexA - indexB;
    });

    return [...trends, ...others].slice(0, 10);
  }, [movies, searchTerm]);

  const handleAddMovie = (movie: Movie) => {
    setMovies(prev => [movie, ...prev]);
  };

  const handleMovieClick = (movie: Movie) => {
    setCurrentMovie(movie);
    setViewState(ViewState.PLAYER);
  };

  const handleBackToHome = () => {
    setCurrentMovie(null);
    setViewState(ViewState.HOME);
  };

  return (
    <div className="min-h-screen bg-[#0f1014] text-white font-sans selection:bg-brand-500 selection:text-white pb-20 overflow-x-hidden">
      {/* Detail View (Formerly Player) */}
      {viewState === ViewState.PLAYER && currentMovie ? (
        <Player movie={currentMovie} onBack={handleBackToHome} />
      ) : (
        <>
          <Navbar 
            onAddClick={() => setIsModalOpen(true)}
            onHomeClick={() => setViewState(ViewState.HOME)}
            searchTerm={searchTerm}
            onSearchChange={setSearchTerm}
          />

          <main>

            {/* Hero Section - Immersive Cinematic Style */}
            {!searchTerm && movies.length > 0 && (
              <div className="relative w-full h-[75vh] md:h-[85vh] mb-[-60px] md:mb-[-100px]">
                 {/* Background Image */}
                 <div className="absolute inset-0">
                    <img 
                        src={movies[0].posterUrl} 
                        alt="Hero Cover"
                        className="w-full h-full object-cover object-top mask-image-gradient"
                    />
                    {/* Cinematic Gradients - Stronger at bottom for text readability */}
                    <div className="absolute inset-0 bg-gradient-to-r from-[#0f1014] via-[#0f1014]/50 to-transparent" />
                    <div className="absolute inset-0 bg-gradient-to-t from-[#0f1014] via-[#0f1014]/40 to-transparent" />
                 </div>

                 {/* Content */}
                 <div className="absolute inset-0 flex items-center">
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 w-full mt-16 md:mt-20">
                        <div className="max-w-2xl space-y-4 md:space-y-6 animate-fade-in-up">
                             <div className="flex items-center space-x-2 text-brand-500 font-bold tracking-wider text-xs md:text-sm uppercase">
                                <span className="px-2 py-0.5 border border-brand-500 rounded bg-brand-500/10">Novedad</span>
                                <span className="hidden sm:inline">Película #1 en Tendencias</span>
                             </div>

                            {/* Responsive Title: Smaller on mobile, massive on desktop */}
                            <h1 className="text-4xl sm:text-5xl md:text-7xl font-black text-white leading-tight drop-shadow-2xl">
                                {movies[0].title}
                            </h1>

                            <div className="flex items-center space-x-3 text-gray-300 text-xs md:text-sm font-medium">
                                <span className="text-green-400 font-bold">98% Match</span>
                                <span>{movies[0].year}</span>
                                <span className="px-1.5 py-0.5 border border-gray-500 rounded text-[10px] md:text-xs">HD</span>
                                <span className="line-clamp-1">{movies[0].genre.join(' • ')}</span>
                            </div>

                            {/* Description hidden on very small screens to prioritize buttons */}
                            <p className="text-gray-200 text-sm md:text-lg line-clamp-3 md:line-clamp-4 leading-relaxed drop-shadow-md max-w-xl hidden sm:block">
                                {movies[0].description}
                            </p>

                            <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3 pt-2 md:pt-4">
                                <button 
                                    onClick={() => handleMovieClick(movies[0])}
                                    className="flex items-center justify-center px-6 md:px-8 py-3 md:py-4 bg-white text-black font-bold text-base md:text-lg rounded hover:bg-gray-200 transition-all transform hover:scale-105 active:scale-95 shadow-[0_0_20px_rgba(255,255,255,0.3)]"
                                >
                                    <Play className="h-5 w-5 md:h-6 md:w-6 mr-2 md:mr-3 fill-black" />
                                    Ver Ahora
                                </button>
                                <button 
                                    onClick={() => handleMovieClick(movies[0])}
                                    className="flex items-center justify-center px-6 md:px-8 py-3 md:py-4 bg-[#6d6d6eb3] hover:bg-[#6d6d6e80] text-white font-bold text-base md:text-lg rounded transition-colors backdrop-blur-sm active:scale-95"
                                >
                                    <Info className="h-5 w-5 md:h-6 md:w-6 mr-2 md:mr-3" />
                                    <span className="sm:hidden">Info</span>
                                    <span className="hidden sm:inline">Más Información</span>
                                </button>
                            </div>
                        </div>
                    </div>
                 </div>
              </div>
            )}

            {/* Movies Content */}
            <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-4 md:pt-0">

                {/* Trending Section */}
                {!searchTerm && trendingMovies.length > 0 && (
                    <div className="mb-10 mt-[-20px] md:mt-0">
                        <h2 className="text-xl md:text-2xl font-bold text-white mb-4">Tendencias</h2>
                        <div className="flex gap-4 overflow-x-auto pb-4 pt-2 snap-x hide-scrollbar -mx-4 px-4 sm:mx-0 sm:px-0">
                            {trendingMovies.map((movie, index) => (
                                <div key={movie.id} className="min-w-[140px] md:min-w-[180px] snap-start">
                                    <MovieCard movie={movie} onClick={handleMovieClick} rank={index + 1} />
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                <div className="mb-4 md:mb-6 flex items-end justify-between">
                    <h2 className="text-xl md:text-2xl font-bold text-white flex items-center">
                        {searchTerm ? `Resultados: "${searchTerm}"` : 'Catálogo Estelar'}
                    </h2>
                </div>

                {filteredMovies.length > 0 ? (
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 sm:gap-6">
                    {filteredMovies.map(movie => (
                    <MovieCard key={movie.id} movie={movie} onClick={handleMovieClick} />
                    ))}
                </div>
                ) : (
                <div className="flex flex-col items-center justify-center py-20 md:py-32 text-gray-500 text-center px-4">
                    <div className="bg-gray-800/50 p-6 rounded-full mb-4">
                        <Info className="h-10 w-10 text-gray-400" />
                    </div>
                    <p className="text-lg md:text-xl font-medium">No encontramos "{searchTerm}"</p>
                    <button 
                        onClick={() => setIsModalOpen(true)}
                        className="mt-4 text-brand-500 hover:text-white transition-colors flex items-center"
                    >
                        <Plus className="h-4 w-4 mr-2" />
                        Agregar manualmente
                    </button>
                </div>
                )}
            </div>
          </main>

          {/* Modal */}
          {isModalOpen && (
            <AddMovieModal 
              onClose={() => setIsModalOpen(false)} 
              onAdd={handleAddMovie} 
            />
          )}
        </>
      )}
    </div>
  );
};

