      </div>

      {/* Additional Info Section & More Like This */}
      <div className="max-w-7xl mx-auto px-5 sm:px-10 py-6 md:py-10 border-t border-gray-800 mt-[-20px] md:mt-[-50px] relative z-10 bg-[#141414]">

         <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 text-sm text-gray-400 mb-10">
            <div>
                <span className="block text-gray-500 mb-1">Director</span>
                James Cameron
            </div>
             <div>
                <span className="block text-gray-500 mb-1">Elenco Principal</span>
                Sam Worthington, Zoe Saldaña, Sigourney Weaver, Stephen Lang
            </div>
             <div>
                <span className="block text-gray-500 mb-1">Géneros</span>
                {movie.genre.join(', ')}
            </div>
         </div>

         {/* More Like This Section */}
         {recommendations.length > 0 && (
             <div className="animate-fade-in-up">
                 <h2 className="text-xl md:text-2xl font-bold text-white mb-6 flex items-center gap-2">
                    <span className="bg-brand-500 w-1 h-6 rounded-full inline-block"></span>
                    Más como esto
                 </h2>
                 <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 sm:gap-6">
                    {recommendations.map(recMovie => (
                        <MovieCard key={recMovie.id} movie={recMovie} onClick={onMovieClick} />
                    ))}
                 </div>
             </div>
         )}
      </div>
    </div>
  );
};

