const App: React.FC = () => {
  const [movies, setMovies] = useState<Movie[]>(INITIAL_MOVIES);
  const [viewState, setViewState] = useState<ViewState>(ViewState.HOME);
  const [currentMovie, setCurrentMovie] = useState<Movie | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);

  // State for Likes and My List
  const [myListIds, setMyListIds] = useState<string[]>([]);
  const [likedMovieIds, setLikedMovieIds] = useState<string[]>([]);

  // Toggle Handlers
  const toggleMyList = (movieId: string) => {
    setMyListIds(prev => 
      prev.includes(movieId) ? prev.filter(id => id !== movieId) : [...prev, movieId]
    );
  };

  const toggleLike = (movieId: string) => {
    setLikedMovieIds(prev => 
      prev.includes(movieId) ? prev.filter(id => id !== movieId) : [...prev, movieId]
    );
  };

  const filteredMovies = useMemo(() => {
    // If in My List view, filter by list IDs
    const sourceMovies = viewState === ViewState.MY_LIST 
      ? movies.filter(m => myListIds.includes(m.id)) 
      : movies;

    return sourceMovies.filter(m => 
      m.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
      m.genre.some(g => g.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [movies, searchTerm, viewState, myListIds]);

  // Derived Trending List
  const trendingMovies = useMemo(() => {
    if (searchTerm || viewState === ViewState.MY_LIST) return [];

    const priorityTitles = [
        "Stranger Things",      // #1
        "Gran Diluvio",         // #2
        "Estado de fuga",       // #3
        "Oppenheimer",          // #4
        "Beso Dinamita",        // #5
        "Welcome to Derry",     // #6
        "Zootopia 2",           // #7
        "Drácula",              // #8
        "Emily in Paris",       // #9
        "Conjuring"             // #10
    ];

    const trends: Movie[] = [];
    const others: Movie[] = [];

    movies.forEach(m => {
        if (priorityTitles.some(pt => m.title.includes(pt))) {
            trends.push(m);
        } else {
            others.push(m);
        }
    });

    trends.sort((a, b) => {
        const indexA = priorityTitles.findIndex(pt => a.title.includes(pt));
        const indexB = priorityTitles.findIndex(pt => b.title.includes(pt));
        return indexA - indexB;
    });

    return [...trends, ...others].slice(0, 10);
  }, [movies, searchTerm, viewState]);

  const handleAddMovie = (movie: Movie) => {
    setMovies(prev => [movie, ...prev]);
  };

  const handleMovieClick = (movie: Movie) => {
    setCurrentMovie(movie);
    setViewState(ViewState.PLAYER);
  };

  const handleBackToHome = () => {
    setCurrentMovie(null);
    setViewState(ViewState.HOME);
  };

  return (
    <div className="min-h-screen bg-[#0f1014] text-white font-sans selection:bg-brand-500 selection:text-white pb-20 overflow-x-hidden">
      {/* Detail View */}
      {viewState === ViewState.PLAYER && currentMovie ? (
        <Player 
          movie={currentMovie}
          allMovies={movies}
          onBack={handleBackToHome}
          onMovieClick={handleMovieClick}
          isLiked={likedMovieIds.includes(currentMovie.id)}
          isInMyList={myListIds.includes(currentMovie.id)}
          onToggleLike={() => toggleLike(currentMovie.id)}
          onToggleMyList={() => toggleMyList(currentMovie.id)}
        />
      ) : (
        <>
          <Navbar 
            onAddClick={() => setIsModalOpen(true)}
            onHomeClick={() => setViewState(ViewState.HOME)}
            onMyListClick={() => setViewState(ViewState.MY_LIST)}
            searchTerm={searchTerm}
            onSearchChange={setSearchTerm}
          />

          <main>

            {/* Hero Section - Only Show on Home View (not My List) and no search */}
            {viewState === ViewState.HOME && !searchTerm && movies.length > 0 && (
              <div className="relative w-full h-[75vh] md:h-[85vh] mb-[-60px] md:mb-[-100px]">
                 {/* Background Image */}
                 <div className="absolute inset-0">
                    <img 
                        src={movies[0].posterUrl} 
                        alt="Hero Cover"
                        className="w-full h-full object-cover object-top mask-image-gradient"
                    />
                    <div className="absolute inset-0 bg-gradient-to-r from-[#0f1014] via-[#0f1014]/50 to-transparent" />
                    <div className="absolute inset-0 bg-gradient-to-t from-[#0f1014] via-[#0f1014]/40 to-transparent" />
                 </div>

                 {/* Content */}
                 <div className="absolute inset-0 flex items-center">
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 w-full mt-16 md:mt-20">
                        <div className="max-w-2xl space-y-4 md:space-y-6 animate-fade-in-up">
                             <div className="flex items-center space-x-2 text-brand-500 font-bold tracking-wider text-xs md:text-sm uppercase">
                                <span className="px-2 py-0.5 border border-brand-500 rounded bg-brand-500/10">Novedad</span>
                                <span className="hidden sm:inline">Película #1 en Tendencias</span>
                             </div>

                            <h1 className="text-4xl sm:text-5xl md:text-7xl font-black text-white leading-tight drop-shadow-2xl">
                                {movies[0].title}
                            </h1>

                            <div className="flex items-center space-x-3 text-gray-300 text-xs md:text-sm font-medium">
                                <span className="text-green-400 font-bold">98% Match</span>
                                <span>{movies[0].year}</span>
                                <span className="px-1.5 py-0.5 border border-gray-500 rounded text-[10px] md:text-xs">HD</span>
                                <span className="line-clamp-1">{movies[0].genre.join(' • ')}</span>
                            </div>

                            <p className="text-gray-200 text-sm md:text-lg line-clamp-3 md:line-clamp-4 leading-relaxed drop-shadow-md max-w-xl hidden sm:block">
                                {movies[0].description}
                            </p>

                            <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3 pt-2 md:pt-4">
                                <button 
                                    onClick={() => handleMovieClick(movies[0])}
                                    className="flex items-center justify-center px-6 md:px-8 py-3 md:py-4 bg-white text-black font-bold text-base md:text-lg rounded hover:bg-gray-200 transition-all transform hover:scale-105 active:scale-95 shadow-[0_0_20px_rgba(255,255,255,0.3)]"
                                >
                                    <Play className="h-5 w-5 md:h-6 md:w-6 mr-2 md:mr-3 fill-black" />
                                    Ver Ahora
                                </button>
                                <button 
                                    onClick={() => handleMovieClick(movies[0])}
                                    className="flex items-center justify-center px-6 md:px-8 py-3 md:py-4 bg-[#6d6d6eb3] hover:bg-[#6d6d6e80] text-white font-bold text-base md:text-lg rounded transition-colors backdrop-blur-sm active:scale-95"
                                >
                                    <Info className="h-5 w-5 md:h-6 md:w-6 mr-2 md:mr-3" />
                                    <span className="sm:hidden">Info</span>
                                    <span className="hidden sm:inline">Más Información</span>
                                </button>
                            </div>
                        </div>
                    </div>
                 </div>
              </div>
            )}

            {/* Movies Content */}
            <div className={`relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 ${viewState === ViewState.HOME && !searchTerm ? 'pt-4 md:pt-0' : 'pt-24'}`}>

                {/* Trending Section - Home Only */}
                {viewState === ViewState.HOME && !searchTerm && trendingMovies.length > 0 && (
                    <div className="mb-10 mt-[-20px] md:mt-0">
                        <h2 className="text-xl md:text-2xl font-bold text-white mb-4">Tendencias</h2>
                        <div className="flex gap-4 overflow-x-auto pb-4 pt-2 snap-x hide-scrollbar -mx-4 px-4 sm:mx-0 sm:px-0">
                            {trendingMovies.map((movie, index) => (
                                <div key={movie.id} className="min-w-[140px] md:min-w-[180px] snap-start">
                                    <MovieCard movie={movie} onClick={handleMovieClick} rank={index + 1} />
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                <div className="mb-4 md:mb-6 flex items-end justify-between">
                    <h2 className="text-xl md:text-2xl font-bold text-white flex items-center">
                        {searchTerm 
                            ? `Resultados: "${searchTerm}"` 
                            : viewState === ViewState.MY_LIST 
                                ? 'Mi Lista' 
                                : 'Catálogo Estelar'}
                    </h2>
                </div>

                {filteredMovies.length > 0 ? (
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 sm:gap-6">
                    {filteredMovies.map(movie => (
                    <MovieCard key={movie.id} movie={movie} onClick={handleMovieClick} />
                    ))}
                </div>
                ) : (
                <div className="flex flex-col items-center justify-center py-20 md:py-32 text-gray-500 text-center px-4">
                    <div className="bg-gray-800/50 p-6 rounded-full mb-4">
                        {viewState === ViewState.MY_LIST ? (
                            <Plus className="h-10 w-10 text-gray-400" />
                        ) : (
                            <Info className="h-10 w-10 text-gray-400" />
                        )}
                    </div>
                    <p className="text-lg md:text-xl font-medium">
                        {viewState === ViewState.MY_LIST 
                            ? "Aún no has agregado películas a tu lista."
                            : `No encontramos "${searchTerm}"`}
                    </p>
                    {viewState === ViewState.MY_LIST && (
                        <button 
                            onClick={() => setViewState(ViewState.HOME)}
                            className="mt-4 text-brand-500 hover:text-white transition-colors flex items-center"
                        >
                            <ChevronLeft className="h-4 w-4 mr-2" />
                            Volver al Catálogo
                        </button>
                    )}
                     {viewState === ViewState.HOME && (
                        <button 
                            onClick={() => setIsModalOpen(true)}
                            className="mt-4 text-brand-500 hover:text-white transition-colors flex items-center"
                        >
                            <Plus className="h-4 w-4 mr-2" />
                            Agregar manualmente
                        </button>
                     )}
                </div>
                )}
            </div>
          </main>

          {/* Modal */}
          {isModalOpen && (
            <AddMovieModal 
              onClose={() => setIsModalOpen(false)} 
              onAdd={handleAddMovie} 
            />
          )}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useRef } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { Movie } from '../types';
import { MovieCard } from './MovieCard';

interface MovieRowProps {
  title: string;
  movies: Movie[];
  onMovieClick: (movie: Movie) => void;
  rank?: boolean;
}

export const MovieRow: React.FC<MovieRowProps> = ({ title, movies, onMovieClick, rank }) => {
  const rowRef = useRef<HTMLDivElement>(null);

  const slide = (offset: number) => {
    if (rowRef.current) {
      rowRef.current.scrollLeft += offset;
    }
  };

  if (movies.length === 0) return null;

  return (
    <div className="mb-8 md:mb-12 relative group/row">
      <h2 className="text-xl md:text-2xl font-bold text-white mb-3 md:mb-4 px-4 sm:px-6 lg:px-8 flex items-end gap-3">
         {title}
         <span className="text-xs font-semibold text-brand-500 opacity-0 group-hover/row:opacity-100 transition-opacity cursor-pointer mb-1 flex items-center hover:text-white">
            Explorar todo <ChevronRight className="h-3 w-3 ml-0.5" />
         </span>
      </h2>

      <div className="relative group">
        <div 
            className="absolute top-0 bottom-0 left-0 z-40 w-12 bg-gradient-to-r from-[#0f1014]/80 to-transparent hidden md:block pointer-events-none"
        />

        <ChevronLeft 
            className="absolute top-0 bottom-0 left-2 z-50 m-auto h-12 w-12 cursor-pointer opacity-0 group-hover:opacity-100 transition-all hover:scale-110 text-white drop-shadow-lg hidden md:block bg-black/30 rounded-full p-2 hover:bg-black/60" 
            onClick={() => slide(-800)}
        />

        <div 
            ref={rowRef}
            className="flex gap-4 overflow-x-scroll scroll-smooth hide-scrollbar px-4 sm:px-6 lg:px-8 pb-8 pt-4"
        >
          {movies.map((movie, index) => (
            <div key={movie.id} className={`flex-none ${rank ? 'min-w-[160px] md:min-w-[220px]' : 'min-w-[140px] md:min-w-[200px]'}`}>
              <MovieCard 
                movie={movie} 
                onClick={onMovieClick} 
                rank={rank ? index + 1 : undefined} 
              />
            </div>
          ))}
        </div>

        <ChevronRight 
            className="absolute top-0 bottom-0 right-2 z-50 m-auto h-12 w-12 cursor-pointer opacity-0 group-hover:opacity-100 transition-all hover:scale-110 text-white drop-shadow-lg hidden md:block bg-black/30 rounded-full p-2 hover:bg-black/60" 
            onClick={() => slide(800)}
        />

         <div 
            className="absolute top-0 bottom-0 right-0 z-40 w-12 bg-gradient-to-l from-[#0f1014]/80 to-transparent hidden md:block pointer-events-none"
        />
      </div>
    </div>
  );
};

