const App: React.FC = () => {
  const [movies, setMovies] = useState<Movie[]>(INITIAL_MOVIES);
  const [viewState, setViewState] = useState<ViewState>(ViewState.HOME);
  const [currentMovie, setCurrentMovie] = useState<Movie | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);

  // State for Likes and My List
  const [myListIds, setMyListIds] = useState<string[]>([]);
  const [likedMovieIds, setLikedMovieIds] = useState<string[]>([]);

  // Toggle Handlers
  const toggleMyList = (movieId: string) => {
    setMyListIds(prev => 
      prev.includes(movieId) ? prev.filter(id => id !== movieId) : [...prev, movieId]
    );
  };

  const toggleLike = (movieId: string) => {
    setLikedMovieIds(prev => 
      prev.includes(movieId) ? prev.filter(id => id !== movieId) : [...prev, movieId]
    );
  };

  // 1. Logic for search filtering (Grid View)
  const filteredMovies = useMemo(() => {
    // If in My List view, filter by list IDs
    const sourceMovies = viewState === ViewState.MY_LIST 
      ? movies.filter(m => myListIds.includes(m.id)) 
      : movies;

    return sourceMovies.filter(m => 
      m.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
      m.genre.some(g => g.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [movies, searchTerm, viewState, myListIds]);

  // 2. Logic for Home Page Rows
  const moviesByGenre = useMemo(() => {
    // Helper to find matches
    const getMatches = (keywords: string[]) => 
      movies.filter(m => m.genre.some(g => keywords.some(k => g.toLowerCase().includes(k.toLowerCase()))));

    // Explicit categories
    const categories: Record<string, Movie[]> = {
      'Estrenos y Novedades': movies.filter(m => m.year === '2025'),
      'Series de TV': getMatches(['Serie']),
      'Películas de Terror': getMatches(['Terror', 'Horror', 'Suspenso']),
      'Ciencia Ficción y Fantasía': getMatches(['Sci-Fi', 'Ciencia', 'Fantasía']),
      'Acción y Aventura': getMatches(['Acción', 'Action', 'Aventura']),
      'Animación y Familia': getMatches(['Animación', 'Familia', 'Comedia']),
      'Dramas Aclamados': getMatches(['Drama', 'Biografía']),
    };

    // Remove empty categories
    return Object.fromEntries(Object.entries(categories).filter(([_, list]) => list.length > 0));
  }, [movies]);

  // Derived Trending List
  const trendingMovies = useMemo(() => {
    const priorityTitles = [
        "Stranger Things",      // #1
        "Gran Diluvio",         // #2
        "Estado de fuga",       // #3
        "Oppenheimer",          // #4
        "Beso Dinamita",        // #5
        "Welcome to Derry",     // #6
        "Zootopia 2",           // #7
        "Drácula",              // #8
        "Emily in Paris",       // #9
        "Conjuring"             // #10
    ];

    const trends: Movie[] = [];
    const others: Movie[] = [];

    movies.forEach(m => {
        if (priorityTitles.some(pt => m.title.includes(pt))) {
            trends.push(m);
        } else {
            others.push(m);
        }
    });

    trends.sort((a, b) => {
        const indexA = priorityTitles.findIndex(pt => a.title.includes(pt));
        const indexB = priorityTitles.findIndex(pt => b.title.includes(pt));
        return indexA - indexB;
    });

    return [...trends, ...others].slice(0, 10);
  }, [movies]);

  const myListMovies = useMemo(() => movies.filter(m => myListIds.includes(m.id)), [movies, myListIds]);

  const handleAddMovie = (movie: Movie) => {
    setMovies(prev => [movie, ...prev]);
  };

  const handleMovieClick = (movie: Movie) => {
    setCurrentMovie(movie);
    setViewState(ViewState.PLAYER);
  };

  const handleBackToHome = () => {
    setCurrentMovie(null);
    setViewState(ViewState.HOME);
  };

  return (
    <div className="min-h-screen bg-[#0f1014] text-white font-sans selection:bg-brand-500 selection:text-white pb-20 overflow-x-hidden">
      {/* Detail View */}
      {viewState === ViewState.PLAYER && currentMovie ? (
        <Player 
          movie={currentMovie}
          allMovies={movies}
          onBack={handleBackToHome}
          onMovieClick={handleMovieClick}
          isLiked={likedMovieIds.includes(currentMovie.id)}
          isInMyList={myListIds.includes(currentMovie.id)}
          onToggleLike={() => toggleLike(currentMovie.id)}
          onToggleMyList={() => toggleMyList(currentMovie.id)}
        />
      ) : (
        <>
          <Navbar 
            onAddClick={() => setIsModalOpen(true)}
            onHomeClick={() => setViewState(ViewState.HOME)}
            onMyListClick={() => setViewState(ViewState.MY_LIST)}
            searchTerm={searchTerm}
            onSearchChange={setSearchTerm}
          />

          <main>

            {/* Hero Section - Only Show on Home View (not My List) and no search */}
            {viewState === ViewState.HOME && !searchTerm && movies.length > 0 && (
              <div className="relative w-full h-[85vh] md:h-[95vh] mb-0">
                 {/* Background Image */}
                 <div className="absolute inset-0">
                    <img 
                        src={movies[0].posterUrl} 
                        alt="Hero Cover"
                        className="w-full h-full object-cover object-top mask-image-gradient"
                    />
                    <div className="absolute inset-0 bg-gradient-to-r from-[#0f1014] via-[#0f1014]/40 to-transparent" />
                    <div className="absolute inset-0 bg-gradient-to-t from-[#0f1014] via-[#0f1014]/20 to-transparent" />
                    <div className="absolute bottom-0 left-0 right-0 h-40 bg-gradient-to-t from-[#0f1014] to-transparent" />
                 </div>

                 {/* Content */}
                 <div className="absolute inset-0 flex items-center">
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 w-full mt-20">
                        <div className="max-w-2xl space-y-4 md:space-y-6 animate-fade-in-up">
                             <div className="flex items-center space-x-2 text-brand-500 font-bold tracking-wider text-xs md:text-sm uppercase">
                                <span className="px-2 py-0.5 border border-brand-500 rounded bg-brand-500/10 backdrop-blur-md">Novedad</span>
                                <span className="hidden sm:inline drop-shadow-md">#1 en Tendencias hoy</span>
                             </div>

                            <h1 className="text-5xl sm:text-6xl md:text-8xl font-black text-white leading-[0.9] drop-shadow-2xl tracking-tight">
                                {movies[0].title}
                            </h1>

                            <div className="flex items-center space-x-3 text-gray-200 text-xs md:text-sm font-semibold drop-shadow-md">
                                <span className="text-green-400 font-bold">98% para ti</span>
                                <span>{movies[0].year}</span>
                                <span className="px-1.5 py-0.5 border border-gray-400 rounded text-[10px] md:text-xs backdrop-blur-sm">HD</span>
                                <span className="line-clamp-1">{movies[0].genre.join(' • ')}</span>
                            </div>

                            <p className="text-gray-100 text-sm md:text-lg line-clamp-3 md:line-clamp-4 leading-relaxed drop-shadow-lg max-w-xl hidden sm:block font-medium">
                                {movies[0].description}
                            </p>

                            <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3 pt-4">
                                <button 
                                    onClick={() => handleMovieClick(movies[0])}
                                    className="flex items-center justify-center px-8 py-3.5 bg-white text-black font-bold text-lg rounded hover:bg-gray-200 transition-all transform hover:scale-105 active:scale-95 shadow-[0_0_20px_rgba(255,255,255,0.3)]"
                                >
                                    <Play className="h-6 w-6 mr-2 fill-black" />
                                    Ver Ahora
                                </button>
                                <button 
                                    onClick={() => handleMovieClick(movies[0])}
                                    className="flex items-center justify-center px-8 py-3.5 bg-[#6d6d6eb3] hover:bg-[#6d6d6e80] text-white font-bold text-lg rounded transition-colors backdrop-blur-md active:scale-95"
                                >
                                    <Info className="h-6 w-6 mr-2" />
                                    Más Información
                                </button>
                            </div>
                        </div>
                    </div>
                 </div>
              </div>
            )}

            {/* Main Content Area */}
            <div className={`relative z-10 w-full ${viewState === ViewState.HOME && !searchTerm ? '-mt-24 md:-mt-40' : 'pt-24 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8'}`}>

                {/* 1. HOME VIEW (Rows Layout) */}
                {viewState === ViewState.HOME && !searchTerm ? (
                    <div className="flex flex-col gap-2 pb-10">
                         {/* Trending */}
                         {trendingMovies.length > 0 && (
                            <MovieRow title="Tendencias hoy" movies={trendingMovies} onMovieClick={handleMovieClick} rank />
                         )}

                         {/* My List Row - Only if items exist */}
                         {myListMovies.length > 0 && (
                            <MovieRow title="Mi Lista" movies={myListMovies} onMovieClick={handleMovieClick} />
                         )}

                         {/* Dynamic Categories */}
                         {Object.entries(moviesByGenre).map(([title, categoryMovies]) => (
                            <MovieRow 
                                key={title} 
                                title={title} 
                                movies={categoryMovies} 
                                onMovieClick={handleMovieClick} 
                            />
                         ))}
                    </div>
                ) : (

                /* 2. GRID VIEW (Search Results or My List Page) */
                <>
                    <div className="mb-4 md:mb-6 flex items-end justify-between">
                        <h2 className="text-xl md:text-2xl font-bold text-white flex items-center">
                            {searchTerm 
                                ? `Resultados: "${searchTerm}"` 
                                : viewState === ViewState.MY_LIST 
                                    ? 'Mi Lista' 
                                    : 'Catálogo'}
                        </h2>
                    </div>

                    {filteredMovies.length > 0 ? (
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 sm:gap-6">
                        {filteredMovies.map(movie => (
                        <MovieCard key={movie.id} movie={movie} onClick={handleMovieClick} />
                        ))}
                    </div>
                    ) : (
                    <div className="flex flex-col items-center justify-center py-20 md:py-32 text-gray-500 text-center px-4">
                        <div className="bg-gray-800/50 p-6 rounded-full mb-4">
                            {viewState === ViewState.MY_LIST ? (
                                <Plus className="h-10 w-10 text-gray-400" />
                            ) : (
                                <Search className="h-10 w-10 text-gray-400" />
                            )}
                        </div>
                        <p className="text-lg md:text-xl font-medium">
                            {viewState === ViewState.MY_LIST 
                                ? "Aún no has agregado películas a tu lista."
                                : `No encontramos "${searchTerm}"`}
                        </p>
                        {viewState === ViewState.MY_LIST && (
                            <button 
                                onClick={() => setViewState(ViewState.HOME)}
                                className="mt-4 text-brand-500 hover:text-white transition-colors flex items-center"
                            >
                                <ChevronLeft className="h-4 w-4 mr-2" />
                                Volver al Catálogo
                            </button>
                        )}
                        {viewState === ViewState.HOME && (
                            <button 
                                onClick={() => setIsModalOpen(true)}
                                className="mt-4 text-brand-500 hover:text-white transition-colors flex items-center"
                            >
                                <Plus className="h-4 w-4 mr-2" />
                                Agregar manualmente
                            </button>
                        )}
                    </div>
                    )}
                </>
                )}
            </div>
          </main>

          {/* Modal */}
          {isModalOpen && (
            <AddMovieModal 
              onClose={() => setIsModalOpen(false)} 
              onAdd={handleAddMovie} 
            />
          )}
        </>
      )}
    </div>
  );
};

export default App;

export interface Movie {
  id: string;
  title: string;
  description: string;
  year: string;
  genre: string[];
  posterUrl: string;
  streamUrl: string; // The external link (iframe or video file)
  rating: number;
  director?: string;
  actors?: string[];
  imdbId?: string; // Optional IMDB ID for auto-embed
}

