import React, { useState, useEffect } from 'react';
import { Plus, Search, Bell, User } from 'lucide-react';

interface NavbarProps {
  onAddClick: () => void;
  onHomeClick: () => void;
  onMyListClick: () => void;
  searchTerm: string;
  onSearchChange: (val: string) => void;
}

export const Navbar: React.FC<NavbarProps> = ({ onAddClick, onHomeClick, onMyListClick, searchTerm, onSearchChange }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [mobileSearchActive, setMobileSearchActive] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${isScrolled ? 'bg-[#050505]/95 backdrop-blur-sm shadow-lg' : 'bg-gradient-to-b from-black/90 to-transparent'}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16 sm:h-20">

          {/* Left Side: Logo & Menu */}
          <div className={`flex items-center gap-4 md:gap-8 ${mobileSearchActive ? 'hidden sm:flex' : 'flex'}`}>
            <div className="flex items-center cursor-pointer group" onClick={onHomeClick}>
                <span className="text-lg sm:text-2xl md:text-3xl font-black text-[#E50914] tracking-tighter group-hover:scale-105 transition-transform duration-300 drop-shadow-lg">
                SAMSTUDIOS
                </span>
            </div>

            <div className="hidden lg:flex items-center gap-6 text-xs md:text-sm font-medium text-gray-300">
                <button onClick={onHomeClick} className="text-white font-bold hover:text-gray-300 transition-colors">Inicio</button>
                <button className="hover:text-white transition-colors">Series</button>
                <button className="hover:text-white transition-colors">Películas</button>
                <button className="hover:text-white transition-colors">Novedades</button>
                <button onClick={onMyListClick} className="hover:text-white transition-colors">Mi Lista</button>
            </div>
          </div>

          {/* Right Side: Search & Profile */}
          <div className={`flex items-center gap-2 sm:gap-6 ${mobileSearchActive ? 'w-full' : ''}`}>

            <div className={`flex items-center transition-all bg-black/40 border border-white/10 hover:border-white/30 rounded-full px-2 py-1 ${mobileSearchActive ? 'w-full' : ''}`}>
                <Search 
                    className={`h-4 w-4 md:h-5 md:w-5 text-gray-300 cursor-pointer min-w-[20px]`} 
                    onClick={() => setMobileSearchActive(!mobileSearchActive)} 
                />
                <input
                    type="text"
                    className={`bg-transparent border-none focus:ring-0 text-white text-sm placeholder-gray-400 transition-all duration-300 outline-none ml-2 ${searchTerm || mobileSearchActive ? 'w-full sm:w-64' : 'w-0 sm:focus:w-64 focus:w-32'}`}
                    placeholder="Títulos, géneros..."
                    value={searchTerm}
                    onChange={(e) => onSearchChange(e.target.value)}
                    onBlur={() => !searchTerm && setMobileSearchActive(false)}
                />
                {mobileSearchActive && (
                    <button onClick={() => { setMobileSearchActive(false); onSearchChange(''); }} className="sm:hidden p-1">
                         <span className="text-xs text-gray-400">Cancel</span>
                    </button>
                )}
            </div>

            {!mobileSearchActive && (
                <>
                    <button onClick={onAddClick} className="text-gray-200 hover:text-white font-medium text-xs md:text-sm flex items-center gap-1 transition-colors">
                        <Plus className="h-5 w-5 sm:h-4 sm:w-4" /> 
                        <span className="hidden sm:inline">Agregar</span>
                    </button>

                    <Bell className="h-5 w-5 text-gray-200 hover:text-white cursor-pointer hidden sm:block" />

                    <div className="h-7 w-7 sm:h-8 sm:w-8 rounded bg-blue-600 flex items-center justify-center cursor-pointer hover:bg-blue-500 transition-colors">
                        <User className="h-4 w-4 sm:h-5 sm:w-5 text-white" />
                    </div>
                </>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

import React, { useEffect, useState } from 'react';

interface SplashScreenProps {
  onFinish: () => void;
}

export const SplashScreen: React.FC<SplashScreenProps> = ({ onFinish }) => {
  const [animationStep, setAnimationStep] = useState(0);

  useEffect(() => {
    // 1. Initial delay before starting animation
    const t1 = setTimeout(() => setAnimationStep(1), 100); 

    // 2. Fade out animation starts
    const t2 = setTimeout(() => setAnimationStep(2), 2800); 

    // 3. Remove component
    const t3 = setTimeout(onFinish, 3500); 

    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
      clearTimeout(t3);
    };
  }, [onFinish]);

  return (
    <div className={`fixed inset-0 z-[100] bg-black flex items-center justify-center transition-opacity duration-1000 ease-in-out ${animationStep === 2 ? 'opacity-0' : 'opacity-100'}`}>
      <div className="relative flex flex-col items-center justify-center overflow-hidden w-full h-full">

        {/* Cinematic Logo Animation */}
        <div 
          className={`transform transition-all duration-[2500ms] cubic-bezier(0.19, 1, 0.22, 1) flex items-center justify-center ${
            animationStep >= 1 ? 'scale-100 opacity-100 blur-0' : 'scale-150 opacity-0 blur-sm'
          }`}
        >
           <h1 className="text-5xl sm:text-7xl md:text-9xl font-black tracking-tighter text-[#E50914] select-none" style={{ textShadow: '0 0 40px rgba(229, 9, 20, 0.4)' }}>
              SAMSTUDIOS
           </h1>
        </div>

        {/* Loading Spinner / Subtext (Optional, kept minimal for "Pro" look) */}
        <div className={`absolute bottom-20 transition-opacity duration-1000 delay-500 ${animationStep === 1 ? 'opacity-100' : 'opacity-0'}`}>
           <div className="h-1 w-32 bg-gray-900 rounded-full overflow-hidden">
                <div className="h-full bg-[#E50914] w-full animate-[shimmer_1.5s_infinite_translateX(-100%)]" style={{ transform: 'translateX(-100%)', animation: 'progress 1.5s ease-in-out infinite' }}></div>
           </div>
        </div>

        <style>{`
          @keyframes progress {
            0% { transform: translateX(-100%); }
            50% { transform: translateX(0%); }
            100% { transform: translateX(100%); }
          }
        `}</style>
      </div>
    </div>
  );
};

