}

export const SplashScreen: React.FC<SplashScreenProps> = ({ onFinish }) => {
  const [stage, setStage] = useState<'initial' | 'zooming' | 'finished'>('initial');

  useEffect(() => {
    // Stage 1: Start the Zoom Animation shortly after mount
    const t1 = setTimeout(() => setStage('zooming'), 100);

    // Stage 2: Animation is visually done, trigger parent finish to unmount
    const t2 = setTimeout(() => {
        setStage('finished');
        onFinish();
    }, 4500); // 4.5 seconds total duration

    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
    };
  }, [onFinish]);

  return (
    <div 
      className={`fixed inset-0 z-[100] bg-black flex items-center justify-center overflow-hidden transition-opacity duration-1000 ease-out ${
        stage === 'finished' ? 'opacity-0 pointer-events-none' : 'opacity-100'
