import React, { useEffect, useState, useRef } from 'react';

interface SplashScreenProps {
  onFinish: () => void;
}

// URL de un sonido de impacto cinematográfico (libre de derechos o ejemplo)
const INTRO_SOUND_URL = "https://cdn.pixabay.com/download/audio/2022/03/24/audio_c8c8a73467.mp3?filename=cinematic-atmosphere-score-2-22136.mp3"; 

export const SplashScreen: React.FC<SplashScreenProps> = ({ onFinish }) => {
  const [stage, setStage] = useState<'hidden' | 'impact' | 'zooming' | 'finished'>('hidden');
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    // Inicializar Audio
    audioRef.current = new Audio(INTRO_SOUND_URL);
    audioRef.current.volume = 0.5;

    // Timeline de la animación
    const sequence = async () => {
        // 1. Iniciar (Pantalla Negra)
        await new Promise(r => setTimeout(r, 100));

        // 2. IMPACTO (Logo aparece + Sonido + Temblor)
        setStage('impact');
        try {
            await audioRef.current?.play();
        } catch (e) {
            console.log("Autoplay bloqueado por el navegador, se requiere interacción usuario.");
        }
        await new Promise(r => setTimeout(r, 800)); // Mantener el impacto

        // 3. ZOOM (Viaje a la velocidad de la luz)
        setStage('zooming');
        await new Promise(r => setTimeout(r, 2500)); // Duración del zoom

        // 4. FINALIZAR
        setStage('finished');
        onFinish();
    };

    sequence();

    return () => {
        if(audioRef.current) {
            audioRef.current.pause();
            audioRef.current = null;
        }
    };
  }, [onFinish]);

  if (stage === 'finished') return null;

  return (
    <div className="fixed inset-0 z-[100] bg-black flex items-center justify-center overflow-hidden">

        {/* FONDO: Partículas viajando (Warp Speed) */}
        {stage === 'zooming' && (
             <div className="absolute inset-0 z-0">
                <div className="absolute inset-0 bg-[radial-gradient(white,rgba(255,255,255,.2)_2px,transparent_3px)] bg-[length:50px_50px] animate-warp-speed opacity-50"></div>
             </div>
        )}

        {/* CONTENEDOR PRINCIPAL CON PERSPECTIVA */}
        <div className={`relative flex items-center justify-center perspective-container transition-all duration-[2000ms] ease-in-expo
            ${stage === 'hidden' ? 'opacity-0' : 'opacity-100'}
            ${stage === 'zooming' ? 'scale-[50] rotate-1' : 'scale-100'}
        `}>

            {/* LOGO GROUP */}
            <div className={`relative flex flex-col items-center
                ${stage === 'impact' ? 'animate-shake' : ''} 
            `}>

                {/* EFECTO RGB SPLIT (GLITCH) PARA DINAMISMO */}
                {/* Capa Roja (Desplazada) */}
                <h1 className={`text-5xl sm:text-8xl md:text-9xl font-black tracking-tighter text-red-600 absolute top-0 left-0 mix-blend-screen opacity-70
                    ${stage === 'zooming' ? 'animate-rgb-shift-1' : 'opacity-0'}
                `}>
                    SAMSTUDIOS
                </h1>

                {/* Capa Azul (Desplazada) */}
                <h1 className={`text-5xl sm:text-8xl md:text-9xl font-black tracking-tighter text-blue-600 absolute top-0 left-0 mix-blend-screen opacity-70
                    ${stage === 'zooming' ? 'animate-rgb-shift-2' : 'opacity-0'}
                `}>
                    SAMSTUDIOS
                </h1>

                {/* Capa Principal (Blanca/Roja) */}
                <h1 className="text-5xl sm:text-8xl md:text-9xl font-black tracking-tighter text-[#E50914] relative z-10 cinema-text">
                    SAMSTUDIOS
                </h1>

                {/* SUBTITULO */}
                <div className={`mt-4 overflow-hidden transition-all duration-500 ${stage === 'zooming' ? 'opacity-0' : 'opacity-100'}`}>
                    <p className="text-xs sm:text-sm font-bold tracking-[0.8em] text-white uppercase animate-slide-up">
                        Original Production
                    </p>
                </div>
            </div>

            {/* FLASH DE LUZ AL INICIO DEL ZOOM */}
            <div className={`absolute inset-0 bg-white mix-blend-overlay transition-opacity duration-300 pointer-events-none
                ${stage === 'zooming' ? 'opacity-20' : 'opacity-0'}
            `} />
        </div>

        {/* ESTILOS CSS INYECTADOS PARA ANIMACIONES COMPLEJAS */}
        <style>{`
            .perspective-container {
                perspective: 100px;
                transform-style: preserve-3d;
            }
            .cinema-text {
                text-shadow: 0 0 30px rgba(229, 9, 20, 0.8);
            }

            /* Animación de Temblor (Impacto) */
            @keyframes shake {
                0% { transform: translate(1px, 1px) rotate(0deg); }
                10% { transform: translate(-1px, -2px) rotate(-1deg); }
                20% { transform: translate(-3px, 0px) rotate(1deg); }
                30% { transform: translate(3px, 2px) rotate(0deg); }
                40% { transform: translate(1px, -1px) rotate(1deg); }
                50% { transform: translate(-1px, 2px) rotate(-1deg); }
                60% { transform: translate(-3px, 1px) rotate(0deg); }
                70% { transform: translate(3px, 1px) rotate(-1deg); }
                80% { transform: translate(-1px, -1px) rotate(1deg); }
                90% { transform: translate(1px, 2px) rotate(0deg); }
                100% { transform: translate(1px, -2px) rotate(-1deg); }
            }
            .animate-shake {
                animation: shake 0.5s cubic-bezier(.36,.07,.19,.97) both;
            }

            /* Animación de Estrellas/Velocidad */
            @keyframes warp-speed {
                0% { transform: scale(1); opacity: 0; }
                50% { opacity: 0.5; }
                100% { transform: scale(3); opacity: 0; }
            }
            .animate-warp-speed {
                animation: warp-speed 2s linear infinite;
            }

            /* Desplazamiento RGB (Capa 1) */
            @keyframes rgb-shift-1 {
                0% { transform: translate(0); opacity: 0; }
                10% { transform: translate(-5px, -2px); opacity: 0.8; }
                100% { transform: translate(-20px, -10px); opacity: 0; }
            }
            .animate-rgb-shift-1 {
                animation: rgb-shift-1 2s ease-in forwards;
            }

            /* Desplazamiento RGB (Capa 2) */
            @keyframes rgb-shift-2 {
                0% { transform: translate(0); opacity: 0; }
                10% { transform: translate(5px, 2px); opacity: 0.8; }
                100% { transform: translate(20px, 10px); opacity: 0; }
            }
            .animate-rgb-shift-2 {
                animation: rgb-shift-2 2s ease-in forwards;
            }

            @keyframes slide-up {
                from { transform: translateY(100%); opacity: 0; }
                to { transform: translateY(0); opacity: 1; }
            }
            .animate-slide-up {
                animation: slide-up 0.8s ease-out forwards;
            }
            .ease-in-expo {
                transition-timing-function: cubic-bezier(0.95, 0.05, 0.795, 0.035);
            }
        `}</style>
    </div>
  );
};

import React, { useEffect, useState } from 'react';

interface SplashScreenProps {
  onFinish: () => void;
}

export const SplashScreen: React.FC<SplashScreenProps> = ({ onFinish }) => {
  const [animating, setAnimating] = useState(true);

  useEffect(() => {
    // Duración total de la animación (4 segundos aprox)
    const timer = setTimeout(() => {
      setAnimating(false);
      onFinish();
    }, 3800);

    return () => clearTimeout(timer);
  }, [onFinish]);

  if (!animating) return null;

  return (
    <div className="fixed inset-0 z-[100] bg-black flex items-center justify-center overflow-hidden">

      {/* Container de la animación */}
      <div className="relative flex flex-col items-center justify-center w-full h-full animate-intro-sequence">

        {/* LOGO */}
        {/* El logo comienza pequeño, crece un poco (tensión) y luego hace un zoom masivo hacia la cámara */}
        <h1 className="text-6xl sm:text-8xl md:text-9xl font-black tracking-tighter text-[#E50914] select-none scale-100 opacity-0 animate-netflix-pop">
            SAMSTUDIOS
        </h1>

        {/* Sombra/Glow sutil detrás para dar profundidad */}
        <div className="absolute inset-0 bg-gradient-to-r from-transparent via-[#E50914]/10 to-transparent opacity-0 animate-glow-pulse pointer-events-none" />

      </div>

      <style>{`
        /* 
           Secuencia estilo Netflix:
           1. (0-20%) Aparece de golpe (Pop) o fade rápido.
           2. (20-70%) Crece muy lentamente (Tensión).
           3. (70-100%) Zoom masivo hacia la cámara (Entrada a la app).
        */
        @keyframes netflix-pop {
            0% {
                opacity: 0;
                transform: scale(0.8);
            }
            20% {
                opacity: 1;
                transform: scale(1);
            }
            70% {
                opacity: 1;
                transform: scale(1.1); /* Crece sutilmente */
            }
            100% {
                opacity: 0;
                transform: scale(30); /* El usuario "atraviesa" el logo */
            }
        }

        /* El contenedor hace fade-out al final para suavizar la transición a la app */
        @keyframes intro-sequence {
            0% { background-color: black; }
            90% { background-color: black; }
            100% { background-color: transparent; }
        }

        /* Un destello sutil en el fondo */
        @keyframes glow-pulse {
            0% { opacity: 0; }
            30% { opacity: 0.3; }
            100% { opacity: 0; }
        }

        .animate-netflix-pop {
            animation: netflix-pop 3.5s cubic-bezier(0.645, 0.045, 0.355, 1) forwards;
        }

        .animate-intro-sequence {
            animation: intro-sequence 3.8s ease-out forwards;
        }

        .animate-glow-pulse {
            animation: glow-pulse 3.5s ease-in-out forwards;
        }
      `}</style>
    </div>
  );
};

