  useEffect(() => {
    fetchActors();
  }, []);

  const slide = (offset: number) => {
    if (rowRef.current) {
      rowRef.current.scrollLeft += offset;
    }
  };

  const handleEditClick = (actor: Actor) => {
      if (!isAdmin) return;
      setSelectedActor(actor);
      setIsModalOpen(true);
  };

