  const [disclaimerAccepted, setDisclaimerAccepted] = useState(false);
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedMovie, setSelectedMovie] = useState<Movie | null>(null);

  // State for Movies (Fetched + Hardcoded)
  const [movies, setMovies] = useState<Movie[]>(INITIAL_MOVIES);

  const [myList, setMyList] = useState<string[]>([]);
  const [likedMovies, setLikedMovies] = useState<string[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  // Auth State
  const [session, setSession] = useState<any>(null);
  const isAdmin = !!session?.user;

  // 1. Check Auth on Mount
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
    });

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });

    return () => subscription.unsubscribe();
  }, []);

  // 2. Fetch Movies from Supabase on Mount
  useEffect(() => {
    const fetchMovies = async () => {
        const { data, error } = await supabase
            .from('movies')
            .select('*')
            .order('created_at', { ascending: false });

        if (!error && data) {
            // Priority Strategy: Supabase Data > Hardcoded Data
            // If Supabase has data for an ID, it overwrites INITIAL_MOVIES
            // This allows us to "Edit" hardcoded movies by saving them to Supabase
            const movieMap = new Map<string, Movie>();

            // First load hardcoded
            INITIAL_MOVIES.forEach(m => movieMap.set(m.id, m));

            // Then overwrite with Supabase data
            data.forEach((m: any) => movieMap.set(m.id, m));

            setMovies(Array.from(movieMap.values()));
        } else {
            console.error("Error fetching movies:", error);
        }
    };

    fetchMovies();
  }, []);

  const filteredMovies = useMemo(() => {
    if (!searchTerm) return movies;
    return movies.filter(m => 
      m.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      m.genre.some(g => g.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [movies, searchTerm]);

  // Construct the specific Trending List dynamically based on ranking
  const trendingMovies = useMemo(() => {
    return movies
      .filter(m => m.trendingRank && m.trendingRank > 0)
      .sort((a, b) => (a.trendingRank || 100) - (b.trendingRank || 100))
      .slice(0, 10);
  }, [movies]);

  const myListMovies = useMemo(() => {
    return movies.filter(m => myList.includes(m.id));
  }, [movies, myList]);

  const handleMovieClick = (movie: Movie) => {
    setSelectedMovie(movie);
    setCurrentView(ViewState.PLAYER);
  };

  const handleEditMovie = (movie: Movie) => {
      setSelectedMovie(movie);
      setCurrentView(ViewState.EDIT_MOVIE);
  };

  const handleSaveMovie = (savedMovie: Movie) => {
    setMovies(prev => {
        // Update existing or add new
        const exists = prev.find(m => m.id === savedMovie.id);
        if (exists) {
            return prev.map(m => m.id === savedMovie.id ? savedMovie : m);
        }
        return [savedMovie, ...prev];
    });
    // If we were editing, go back to player to see changes
    if (currentView === ViewState.EDIT_MOVIE) {
        setSelectedMovie(savedMovie);
        setCurrentView(ViewState.PLAYER);
    }
  };

  const handleDeleteMovie = async (movieId: string) => {
      // 1. Delete from Supabase
      const { error } = await supabase.from('movies').delete().eq('id', movieId);

      if (error) {
          throw new Error(error.message);
      }

      // 2. Remove from Local State immediately
      setMovies(prev => prev.filter(m => m.id !== movieId));

      // 3. Reset View
      setSelectedMovie(null);
      setCurrentView(ViewState.HOME);
  };

  const toggleMyList = (movieId: string) => {
    setMyList(prev => prev.includes(movieId) ? prev.filter(id => id !== movieId) : [...prev, movieId]);
  };

  const toggleLike = (movieId: string) => {
    setLikedMovies(prev => prev.includes(movieId) ? prev.filter(id => id !== movieId) : [...prev, movieId]);
  };

  const handleLogout = async () => {
      await supabase.auth.signOut();
  };

  if (showSplash) {
    return <SplashScreen onFinish={() => setShowSplash(false)} />;
  }

  if (!disclaimerAccepted) {
    return <DisclaimerModal onAccept={() => setDisclaimerAccepted(true)} />;
  }

  if (currentView === ViewState.PLAYER && selectedMovie) {
    return (
      <Player 
        movie={selectedMovie}
        allMovies={movies}
        onBack={() => setCurrentView(ViewState.HOME)}
        onMovieClick={handleMovieClick}
        isLiked={likedMovies.includes(selectedMovie.id)}
        isInMyList={myList.includes(selectedMovie.id)}
        onToggleLike={() => toggleLike(selectedMovie.id)}
        onToggleMyList={() => toggleMyList(selectedMovie.id)}
        isAdmin={isAdmin}
        onEdit={handleEditMovie}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#141414] text-white font-sans">
      <Navbar 
        onAddClick={() => { setSelectedMovie(null); setCurrentView(ViewState.ADD_MOVIE); }}
        onHomeClick={() => { setCurrentView(ViewState.HOME); setSearchTerm(''); }}
        onMyListClick={() => setCurrentView(ViewState.MY_LIST)}
        onUserClick={() => isAdmin ? handleLogout() : setCurrentView(ViewState.LOGIN)}
        searchTerm={searchTerm}
        onSearchChange={setSearchTerm}
        isAdmin={isAdmin}
      />

      {currentView === ViewState.LOGIN && (
        <LoginModal 
            onClose={() => setCurrentView(ViewState.HOME)}
            onLoginSuccess={() => setCurrentView(ViewState.HOME)}
        />
      )}

      {(currentView === ViewState.ADD_MOVIE || currentView === ViewState.EDIT_MOVIE) && (
        <AddMovieModal 
          onClose={() => currentView === ViewState.EDIT_MOVIE ? setCurrentView(ViewState.PLAYER) : setCurrentView(ViewState.HOME)}
          onAdd={handleSaveMovie}
          onDelete={handleDeleteMovie}
          movieToEdit={currentView === ViewState.EDIT_MOVIE ? selectedMovie : null}
        />
      )}

      {currentView === ViewState.MY_LIST ? (
        <div className="pt-24 px-4 sm:px-8 min-h-screen">
            <h2 className="text-2xl sm:text-3xl font-bold mb-6">Mi Lista</h2>
            {myListMovies.length > 0 ? (
                <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                    {myListMovies.map(movie => (
                        <MovieCard key={movie.id} movie={movie} onClick={handleMovieClick} />
                    ))}
                </div>
            ) : (
                <div className="flex flex-col items-center justify-center h-[50vh] text-gray-500">
                    <p className="text-lg">Tu lista está vacía</p>
                </div>
            )}
        </div>
      ) : (
        <>
           {!searchTerm && (
             <div className="relative h-[70vh] md:h-[85vh] w-full">
                {(() => {
                    const featured = movies[0]; // HERO (Avatar) or First Fetched
                    if (!featured) return null;
                    return (
                        <>
                            <div className="absolute inset-0">
                                <img src={featured.posterUrl} className="w-full h-full object-cover" alt={featured.title} />
                                <div className="absolute inset-0 bg-gradient-to-r from-black via-black/40 to-transparent" />
                                <div className="absolute inset-0 bg-gradient-to-t from-[#141414] via-transparent to-transparent" />
                            </div>
                            <div className="absolute bottom-[20%] left-4 md:left-12 max-w-xl space-y-4 animate-fade-in-up">
                                <h1 className="text-4xl md:text-7xl font-black drop-shadow-2xl">{featured.title}</h1>
                                <p className="text-base md:text-xl drop-shadow-md line-clamp-3 text-gray-200">{featured.description}</p>
                                <div className="flex gap-4 pt-4">
                                    <button 
                                        onClick={() => handleMovieClick(featured)}
                                        className="bg-white text-black px-6 py-3 rounded-lg flex items-center gap-2 font-bold hover:bg-gray-200 transition-colors shadow-lg"
                                    >
                                        <Play className="fill-black h-5 w-5" /> Ver Ahora
                                    </button>
                                    <button 
                                        onClick={() => handleMovieClick(featured)}
                                        className="bg-gray-500/40 text-white px-6 py-3 rounded-lg flex items-center gap-2 font-bold hover:bg-gray-500/60 transition-colors backdrop-blur-md border border-white/10"
                                    >
                                        <Info className="h-5 w-5" /> Más Info
                                    </button>
                                </div>
                            </div>
                        </>
                    )
                })()}
             </div>
           )}

           <div className={`relative z-10 pb-20 ${!searchTerm ? '-mt-24 md:-mt-32' : 'pt-24'}`}>

              {!searchTerm && (
                <>
                    {/* Construction Banner */}
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mb-8">
                        <div className="bg-gradient-to-r from-gray-900 to-gray-800 border-l-4 border-yellow-500 rounded-r-lg p-4 shadow-lg flex items-start gap-4 animate-fade-in">
                            <div className="bg-yellow-500/10 p-2 rounded-full shrink-0">
                                <Construction className="h-6 w-6 text-yellow-500" />
                            </div>
                            <div className="flex-1">
                                <h3 className="text-white font-bold text-sm md:text-base">Catálogo en Construcción</h3>
                                <p className="text-gray-400 text-xs md:text-sm mt-1">
                                    Aún no están todas las películas, pero estamos agregando contenido <strong>todos los días</strong>. 
                                    <br className="hidden sm:block" />
                                    <span className="text-blue-400 inline-flex items-center gap-1 mt-1 cursor-pointer hover:underline">
                                        <MessageSquarePlus className="h-3 w-3" />
                                        Pronto podrás solicitar tus favoritas
                                    </span>
                                </p>
                            </div>
                        </div>
                    </div>

                    <TopActorsRow isAdmin={isAdmin} />
                </>
              )}

              <div className="px-4 md:px-12 space-y-8 mt-8">
                 {searchTerm ? (
                     <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-4">
                        {filteredMovies.map(movie => (
                            <MovieCard key={movie.id} movie={movie} onClick={handleMovieClick} />
                        ))}
                     </div>
                 ) : (
                     <>
                        {/* DYNAMIC TRENDING ROW */}
                        {trendingMovies.length > 0 && (
                            <MovieRow title="Tendencias" movies={trendingMovies} onMovieClick={handleMovieClick} rank />
                        )}

                        <MovieRow title="Novedades" movies={movies.filter(m => ['2025', '2024'].includes(m.year) && !m.trendingRank).slice(0, 10)} onMovieClick={handleMovieClick} />
                        <MovieRow title="Acción y Aventura" movies={movies.filter(m => m.genre.some(g => ['Acción', 'Aventura', 'Sci-Fi', 'Fantasía'].includes(g)))} onMovieClick={handleMovieClick} />
                        <MovieRow title="Romance" movies={movies.filter(m => m.genre.includes('Romance'))} onMovieClick={handleMovieClick} />
                        <MovieRow title="Dramas Aclamados" movies={movies.filter(m => m.genre.includes('Drama'))} onMovieClick={handleMovieClick} />
                     </>
                 )}
              </div>
           </div>
        </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { X, Wand2, Loader2, Link as LinkIcon, Image as ImageIcon, Trophy, Save, Trash2, AlertTriangle, FileText, Calendar, Star, Clapperboard } from 'lucide-react';
import { generateMovieMetadata } from '../services/geminiService';
import { supabase } from '../services/supabaseClient';
import { Movie } from '../types';

interface AddMovieModalProps {
  onClose: () => void;
  onAdd: (movie: Movie) => void;
  onDelete?: (movieId: string) => Promise<void>;
  movieToEdit?: Movie | null;
}

export const AddMovieModal: React.FC<AddMovieModalProps> = ({ onClose, onAdd, onDelete, movieToEdit }) => {
  const [title, setTitle] = useState('');
  const [streamUrl, setStreamUrl] = useState('');
  const [posterUrl, setPosterUrl] = useState('');
  const [trendingRank, setTrendingRank] = useState<string>('');

  // New Manual Fields
  const [description, setDescription] = useState('');
  const [year, setYear] = useState(new Date().getFullYear().toString());
  const [genre, setGenre] = useState('');
  const [rating, setRating] = useState('');

  const [loading, setLoading] = useState(false);
  const [deleteLoading, setDeleteLoading] = useState(false);
  const [error, setError] = useState('');
  const [autoMode, setAutoMode] = useState(true);
  const [status, setStatus] = useState('');
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // Pre-fill data if editing
  useEffect(() => {
    if (movieToEdit) {
        setTitle(movieToEdit.title);
        setStreamUrl(movieToEdit.streamUrl);
        setPosterUrl(movieToEdit.posterUrl);
        setTrendingRank(movieToEdit.trendingRank ? movieToEdit.trendingRank.toString() : '');

        // Fill manual fields
        setDescription(movieToEdit.description);
        setYear(movieToEdit.year);
        setGenre(movieToEdit.genre.join(', '));
        setRating(movieToEdit.rating.toString());

        setAutoMode(false); // Manual mode by default when editing
    }
  }, [movieToEdit]);

  const handleSmartGenerateAndSave = async () => {
    if (!title) {
        setError("Por favor escribe el título de la película.");
        return;
    }
    setLoading(true);
    setError('');

    try {
      let finalDescription = description;
      let finalYear = year;
      let finalGenre: string[] = genre.split(',').map(g => g.trim()).filter(g => g);
      let finalRating = parseFloat(rating) || 0;
      let finalDirector = '';
      let finalActors: string[] = [];
      let finalImdbId = '';

      // 1. Logic for Auto Mode (Generate Data)
      if (autoMode && !movieToEdit) {
          setStatus('Generando metadatos con IA...');
          const metadata = await generateMovieMetadata(title);

          finalDescription = metadata.description;
          finalYear = metadata.year;
          finalGenre = metadata.genre;
          finalRating = metadata.rating;
          finalImdbId = metadata.imdbId || '';

          if (!posterUrl) {
             // Fallback if no poster provided in auto mode
             // In a real app, you might fetch this from an API too
          }
      } 

      // 2. Prepare Final Object
      const finalStreamUrl = streamUrl || (movieToEdit ? movieToEdit.streamUrl : 'https://google.com'); // Placeholder if empty
      const finalPosterUrl = posterUrl || (movieToEdit ? movieToEdit.posterUrl : `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`);
      const finalRank = trendingRank ? parseInt(trendingRank) : null;
      const finalId = movieToEdit ? movieToEdit.id : crypto.randomUUID();

      // Ensure manual fields are respected if not auto
      if (!autoMode) {
          if (!description) finalDescription = 'Sin descripción disponible.';
          if (finalGenre.length === 0) finalGenre = ['General'];
      }

      const movieToSave: Movie = {
        id: finalId,
        title: title,
        streamUrl: finalStreamUrl,
        posterUrl: finalPosterUrl,
        description: finalDescription,
        year: finalYear,
        genre: finalGenre,
        rating: finalRating,
        director: finalDirector, // You could add inputs for these too if needed
        actors: finalActors,
        imdbId: finalImdbId,
        trendingRank: finalRank || undefined
      };

      setStatus('Guardando en Supabase...');

      const { error: dbError } = await supabase
        .from('movies')
        .upsert({
            id: movieToSave.id,
            title: movieToSave.title,
            description: movieToSave.description,
            year: movieToSave.year,
            genre: movieToSave.genre,
            "posterUrl": movieToSave.posterUrl,
            "streamUrl": movieToSave.streamUrl,
            rating: movieToSave.rating,
            director: movieToSave.director,
            actors: movieToSave.actors,
            "imdbId": movieToSave.imdbId,
            "trendingRank": movieToSave.trendingRank
        })
        .select();

      if (dbError) {
        throw new Error(dbError.message);
      }

      onAdd(movieToSave);
      onClose();
    } catch (e: any) {
      setError(e.message || "Error desconocido.");
    } finally {
      setLoading(false);
      setStatus('');
    }
  };

  const handleDelete = async () => {
      if (!movieToEdit || !onDelete) return;
      setDeleteLoading(true);
      try {
          await onDelete(movieToEdit.id);
          onClose();
      } catch (e: any) {
          setError("Error al eliminar: " + e.message);
          setDeleteLoading(false);
      }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center px-4 py-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={onClose} />

      <div className="relative bg-[#1a1c22] rounded-2xl w-full max-w-lg border border-white/10 shadow-2xl flex flex-col max-h-[90vh]">
        <div className="p-5 border-b border-white/10 flex justify-between items-center shrink-0">
          <h2 className="text-xl font-bold text-white flex items-center">
            {movieToEdit ? <Save className="h-5 w-5 mr-2 text-brand-500" /> : <Wand2 className="h-5 w-5 mr-2 text-brand-500" />}
            {movieToEdit ? 'Editar Película' : 'Agregar Película'}
          </h2>
          <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors">
            <X className="h-6 w-6" />
          </button>
        </div>

        <div className="p-5 space-y-5 overflow-y-auto custom-scrollbar">

          {!movieToEdit && (
              <div className="bg-brand-900/50 border border-brand-500/30 rounded-lg p-4">
                <div className="flex items-center justify-between mb-2">
                    <span className="text-sm font-bold text-white">Modo Automático (IA)</span>
                    <button 
                        onClick={() => setAutoMode(!autoMode)}
                        className={`w-10 h-6 rounded-full p-1 transition-colors ${autoMode ? 'bg-brand-500' : 'bg-gray-600'}`}
                    >
                        <div className={`w-4 h-4 bg-white rounded-full shadow-md transform transition-transform ${autoMode ? 'translate-x-4' : ''}`} />
                    </button>
                </div>
                <p className="text-xs text-gray-400">
                    {autoMode ? "La IA escribirá la descripción y datos." : "Tú escribes todos los detalles manualmente."}
                </p>
              </div>
          )}

          <div>
            <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase">Título</label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full bg-[#0f1014] border border-white/10 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-brand-500 outline-none"
              placeholder="Ej: Avatar: Fire and Ash"
            />
          </div>

          {(!autoMode || movieToEdit) && (
              <div className="space-y-4 animate-fade-in">

                  {/* MANUAL FIELDS */}

                  <div>
                    <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase">Link Streaming (Video)</label>
                    <div className="relative">
                      <LinkIcon className="absolute left-3 top-3.5 h-5 w-5 text-gray-500" />
                      <input
                        type="text"
                        value={streamUrl}
                        onChange={(e) => setStreamUrl(e.target.value)}
                        className="w-full bg-[#0f1014] border border-white/10 rounded-lg pl-10 pr-4 py-3 text-white focus:ring-2 focus:ring-brand-500 outline-none"
                        placeholder="https://..."
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase">Link Imagen (Poster)</label>
                    <div className="relative">
                      <ImageIcon className="absolute left-3 top-3.5 h-5 w-5 text-gray-500" />
                      <input
                        type="text"
                        value={posterUrl}
                        onChange={(e) => setPosterUrl(e.target.value)}
                        className="w-full bg-[#0f1014] border border-white/10 rounded-lg pl-10 pr-4 py-3 text-white focus:ring-2 focus:ring-brand-500 outline-none"
                        placeholder="https://imagen.jpg"
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase flex items-center gap-2">
                        <FileText className="h-4 w-4" /> Sinopsis / Descripción
                    </label>
                    <textarea
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        className="w-full bg-[#0f1014] border border-white/10 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-brand-500 outline-none h-24 resize-none"
                        placeholder="Escribe de qué trata la película..."
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase flex items-center gap-2">
                            <Calendar className="h-4 w-4" /> Año
                        </label>
                        <input
                            type="text"
                            value={year}
                            onChange={(e) => setYear(e.target.value)}
                            className="w-full bg-[#0f1014] border border-white/10 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-brand-500 outline-none"
                            placeholder="2025"
                        />
                      </div>
                      <div>
                        <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase flex items-center gap-2">
                            <Star className="h-4 w-4 text-yellow-500" /> Calificación (1-10)
                        </label>
                        <input
                            type="number"
                            max="10"
                            step="0.1"
                            value={rating}
                            onChange={(e) => setRating(e.target.value)}
                            className="w-full bg-[#0f1014] border border-white/10 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-brand-500 outline-none"
                            placeholder="8.5"
                        />
                      </div>
                  </div>

                  <div>
                    <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase flex items-center gap-2">
                        <Clapperboard className="h-4 w-4" /> Géneros (Separados por coma)
                    </label>
                    <input
                        type="text"
                        value={genre}
                        onChange={(e) => setGenre(e.target.value)}
                        className="w-full bg-[#0f1014] border border-white/10 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-brand-500 outline-none"
                        placeholder="Acción, Drama, Sci-Fi"
                    />
                  </div>
              </div>
          )}

          <div>
            <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase flex items-center gap-2">
                <Trophy className="h-4 w-4 text-yellow-500" />
                Ranking Tendencias (Opcional)
            </label>
            <input
                type="number"
                min="1"
                max="10"
                value={trendingRank}
                onChange={(e) => setTrendingRank(e.target.value)}
                className="w-full bg-[#0f1014] border border-white/10 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-yellow-500 outline-none"
                placeholder="Ej: 1 para Top #1"
            />
          </div>

          {error && <p className="text-red-400 text-sm">{error}</p>}
          {status && <p className="text-blue-400 text-sm animate-pulse">{status}</p>}

          <div className="flex gap-3 pt-2">
            <button
                onClick={handleSmartGenerateAndSave}
                disabled={!title || loading || deleteLoading}
                className={`flex-1 py-3 rounded-lg font-bold text-white shadow-lg flex items-center justify-center transition-all ${
                !title || loading || deleteLoading
                    ? 'bg-gray-600 cursor-not-allowed' 
                    : 'bg-gradient-to-r from-brand-500 to-blue-600 hover:from-blue-600 hover:to-blue-700'
                }`}
            >
                {loading ? <Loader2 className="animate-spin h-5 w-5 mr-2" /> : 'Guardar Cambios'}
            </button>

            {movieToEdit && (
                <>
                    {showDeleteConfirm ? (
                        <button
                            onClick={handleDelete}
                            disabled={deleteLoading}
                            className="px-4 py-3 bg-red-600 hover:bg-red-700 text-white rounded-lg font-bold flex items-center gap-2 animate-fade-in"
                        >
                           {deleteLoading ? <Loader2 className="animate-spin h-4 w-4" /> : <AlertTriangle className="h-5 w-5" />}
                           ¿Seguro?
                        </button>
                    ) : (
                        <button
                            onClick={() => setShowDeleteConfirm(true)}
                            className="px-4 py-3 bg-red-900/30 text-red-500 border border-red-500/30 hover:bg-red-900/50 hover:text-red-400 rounded-lg transition-colors flex items-center justify-center"
                            title="Eliminar Película"
                        >
                            <Trash2 className="h-5 w-5" />
                        </button>
                    )}
                </>
            )}
          </div>

        </div>
      </div>
    </div>
  );
};

