  movie: Movie;
  allMovies: Movie[];
  onBack: () => void;
  onMovieClick: (movie: Movie) => void;
  isLiked: boolean;
  isInMyList: boolean;
  onToggleLike: () => void;
  onToggleMyList: () => void;
  isAdmin?: boolean;
  onEdit?: (movie: Movie) => void;
}

export const Player: React.FC<PlayerProps> = ({ 
  movie, 
  onBack, 
  isLiked, 
  isInMyList, 
  onToggleLike, 
  onToggleMyList,
