import React, { useState, useEffect } from 'react';
import { X, Wand2, Loader2, Link as LinkIcon, Image as ImageIcon, Trophy, Save, Trash2, AlertTriangle, FileText, Calendar, Star, Clapperboard, MonitorPlay } from 'lucide-react';
import { generateMovieMetadata } from '../services/geminiService';
import { supabase } from '../services/supabaseClient';
import { Movie } from '../types';

interface AddMovieModalProps {
  onClose: () => void;
  onAdd: (movie: Movie) => void;
  onDelete?: (movieId: string) => Promise<void>;
  movieToEdit?: Movie | null;
}

export const AddMovieModal: React.FC<AddMovieModalProps> = ({ onClose, onAdd, onDelete, movieToEdit }) => {
  const [title, setTitle] = useState('');
  const [streamUrl, setStreamUrl] = useState('');
  const [posterUrl, setPosterUrl] = useState('');
  const [trendingRank, setTrendingRank] = useState<string>('');
  const [isDirectLink, setIsDirectLink] = useState(false);

  const [description, setDescription] = useState('');
  const [year, setYear] = useState(new Date().getFullYear().toString());
  const [genre, setGenre] = useState('');
  const [rating, setRating] = useState('');

  const [loading, setLoading] = useState(false);
  const [deleteLoading, setDeleteLoading] = useState(false);
  const [error, setError] = useState('');
  const [autoMode, setAutoMode] = useState(true);
  const [status, setStatus] = useState('');
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  useEffect(() => {
    if (movieToEdit) {
        setTitle(movieToEdit.title);
        setStreamUrl(movieToEdit.streamUrl);
        setPosterUrl(movieToEdit.posterUrl);
        setTrendingRank(movieToEdit.trendingRank ? movieToEdit.trendingRank.toString() : '');
        setIsDirectLink(!!movieToEdit.isDirectLink);
        setDescription(movieToEdit.description);
        setYear(movieToEdit.year);
        setGenre(movieToEdit.genre.join(', '));
        setRating(movieToEdit.rating.toString());
        setAutoMode(false);
    }
  }, [movieToEdit]);

  const handleSmartGenerateAndSave = async () => {
    if (!title) {
        setError("Por favor escribe el título de la película.");
        return;
    }
    setLoading(true);
    setError('');

    try {
      let finalDescription = description;
      let finalYear = year;
      let finalGenre: string[] = genre.split(',').map(g => g.trim()).filter(g => g);
      let finalRating = parseFloat(rating) || 0;
      let finalImdbId = '';

      if (autoMode && !movieToEdit) {
          setStatus('Generando metadatos con IA...');
          const metadata = await generateMovieMetadata(title);
          finalDescription = metadata.description;
          finalYear = metadata.year;
          finalGenre = metadata.genre;
          finalRating = metadata.rating;
          finalImdbId = metadata.imdbId || '';
      } 

      const finalStreamUrl = streamUrl || (movieToEdit ? movieToEdit.streamUrl : '');
      const finalPosterUrl = posterUrl || (movieToEdit ? movieToEdit.posterUrl : `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`);
      const finalRank = trendingRank ? parseInt(trendingRank) : null;
      const finalId = movieToEdit ? movieToEdit.id : crypto.randomUUID();

      const movieToSave: Movie = {
        id: finalId,
        title: title,
        streamUrl: finalStreamUrl,
        posterUrl: finalPosterUrl,
        description: finalDescription || 'Sin descripción.',
        year: finalYear,
        genre: finalGenre.length > 0 ? finalGenre : ['General'],
        rating: finalRating,
        imdbId: finalImdbId,
        trendingRank: finalRank || undefined,
        isDirectLink: isDirectLink
      };

      setStatus('Guardando...');

      const { error: dbError } = await supabase
        .from('movies')
        .upsert({
            id: movieToSave.id,
            title: movieToSave.title,
            description: movieToSave.description,
            year: movieToSave.year,
            genre: movieToSave.genre,
            posterUrl: movieToSave.posterUrl,
            streamUrl: movieToSave.streamUrl,
            rating: movieToSave.rating,
            imdbId: movieToSave.imdbId,
            trendingRank: movieToSave.trendingRank,
            isDirectLink: movieToSave.isDirectLink
        });

      if (dbError) throw new Error(dbError.message);

      onAdd(movieToSave);
      onClose();
    } catch (e: any) {
      setError(e.message || "Error desconocido.");
    } finally {
      setLoading(false);
      setStatus('');
    }
  };

  const handleDelete = async () => {
      if (!movieToEdit || !onDelete) return;
      setDeleteLoading(true);
      try {
          await onDelete(movieToEdit.id);
          onClose();
      } catch (e: any) {
          setError("Error al eliminar: " + e.message);
          setDeleteLoading(false);
      }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center px-4 py-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={onClose} />

      <div className="relative bg-[#1a1c22] rounded-2xl w-full max-w-lg border border-white/10 shadow-2xl flex flex-col max-h-[90vh]">
        <div className="p-5 border-b border-white/10 flex justify-between items-center shrink-0">
          <h2 className="text-xl font-bold text-white flex items-center">
            {movieToEdit ? <Save className="h-5 w-5 mr-2 text-brand-500" /> : <Wand2 className="h-5 w-5 mr-2 text-brand-500" />}
            {movieToEdit ? 'Editar Película' : 'Agregar Película'}
          </h2>
          <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors">
            <X className="h-6 w-6" />
          </button>
        </div>

        <div className="p-5 space-y-5 overflow-y-auto custom-scrollbar">

          <div className="grid grid-cols-2 gap-3">
              <div className={`p-3 rounded-xl border transition-all cursor-pointer ${autoMode && !movieToEdit ? 'bg-brand-500/10 border-brand-500 text-white' : 'bg-white/5 border-white/10 text-gray-400'}`} onClick={() => !movieToEdit && setAutoMode(true)}>
                  <div className="flex items-center gap-2 mb-1">
                      <Wand2 className="h-4 w-4" />
                      <span className="text-xs font-bold uppercase">IA Auto</span>
                  </div>
                  <p className="text-[10px] opacity-70">Genera datos con Inteligencia Artificial.</p>
              </div>
              <div className={`p-3 rounded-xl border transition-all cursor-pointer ${!autoMode || movieToEdit ? 'bg-blue-500/10 border-blue-500 text-white' : 'bg-white/5 border-white/10 text-gray-400'}`} onClick={() => setAutoMode(false)}>
                  <div className="flex items-center gap-2 mb-1">
                      <FileText className="h-4 w-4" />
                      <span className="text-xs font-bold uppercase">Manual</span>
                  </div>
                  <p className="text-[10px] opacity-70">Tú controlas cada detalle del contenido.</p>
              </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase">Título de la Obra</label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full bg-[#0f1014] border border-white/10 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-brand-500 outline-none"
              placeholder="Ej: Avatar: Fire and Ash"
            />
          </div>

          <div className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase">Link del Video / Servidor</label>
                <div className="relative">
                  <LinkIcon className="absolute left-3 top-3.5 h-5 w-5 text-gray-500" />
                  <input
                    type="text"
                    value={streamUrl}
                    onChange={(e) => setStreamUrl(e.target.value)}
                    className="w-full bg-[#0f1014] border border-white/10 rounded-lg pl-10 pr-4 py-3 text-white focus:ring-2 focus:ring-brand-500 outline-none"
                    placeholder="https://terabox.com/embed/..."
                  />
                </div>
              </div>

              {/* TOGGLE FOR DIRECT LINK */}
              <div className="bg-white/5 border border-white/10 rounded-xl p-4 flex items-center justify-between group hover:border-blue-500/30 transition-colors">
                  <div className="flex items-center gap-3">
                      <div className={`p-2 rounded-lg ${isDirectLink ? 'bg-blue-500/20 text-blue-400' : 'bg-gray-800 text-gray-500'}`}>
                        <MonitorPlay className="h-5 w-5" />
                      </div>
                      <div>
                        <span className="block text-sm font-bold text-white">Modo Reproductor Nativo</span>
                        <span className="block text-[10px] text-gray-500">Usa nuestro reproductor pro (Para enlaces directos .mp4)</span>
                      </div>
                  </div>
                  <button 
                    onClick={() => setIsDirectLink(!isDirectLink)}
                    className={`w-12 h-6 rounded-full p-1 transition-colors ${isDirectLink ? 'bg-blue-500' : 'bg-gray-700'}`}
                  >
                    <div className={`w-4 h-4 bg-white rounded-full shadow-md transform transition-transform ${isDirectLink ? 'translate-x-6' : ''}`} />
                  </button>
              </div>

              {(!autoMode || movieToEdit) && (
                <div className="space-y-4 animate-fade-in">
                    <div>
                      <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase">Link Imagen (Poster)</label>
                      <div className="relative">
                        <ImageIcon className="absolute left-3 top-3.5 h-5 w-5 text-gray-500" />
                        <input
                          type="text"
                          value={posterUrl}
                          onChange={(e) => setPosterUrl(e.target.value)}
                          className="w-full bg-[#0f1014] border border-white/10 rounded-lg pl-10 pr-4 py-3 text-white focus:ring-2 focus:ring-brand-500 outline-none"
                          placeholder="https://imagen.jpg"
                        />
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                          <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase tracking-tighter">Año</label>
                          <input type="text" value={year} onChange={(e) => setYear(e.target.value)} className="w-full bg-[#0f1014] border border-white/10 rounded-lg px-4 py-2 text-white outline-none" />
                        </div>
                        <div>
                          <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase tracking-tighter">Rating</label>
                          <input type="number" step="0.1" value={rating} onChange={(e) => setRating(e.target.value)} className="w-full bg-[#0f1014] border border-white/10 rounded-lg px-4 py-2 text-white outline-none" />
                        </div>
                    </div>
                </div>
              )}
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase flex items-center gap-2">
                <Trophy className="h-4 w-4 text-yellow-500" />
                Ranking Tendencias (1-10)
            </label>
            <input
                type="number"
                min="1"
                max="10"
                value={trendingRank}
                onChange={(e) => setTrendingRank(e.target.value)}
                className="w-full bg-[#0f1014] border border-white/10 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-yellow-500 outline-none"
                placeholder="Opcional"
            />
          </div>

          {error && <p className="text-red-400 text-xs bg-red-900/20 p-2 rounded">{error}</p>}
          {status && <p className="text-blue-400 text-xs animate-pulse">{status}</p>}

          <div className="flex gap-3 pt-4">
            <button
                onClick={handleSmartGenerateAndSave}
                disabled={!title || loading || deleteLoading}
                className="flex-1 py-4 rounded-xl font-bold text-white shadow-lg bg-gradient-to-r from-brand-500 to-red-700 hover:scale-[1.02] active:scale-[0.98] transition-all flex items-center justify-center disabled:opacity-50"
            >
                {loading ? <Loader2 className="animate-spin h-5 w-5" /> : 'Guardar y Publicar'}
            </button>

            {movieToEdit && (
                <button
                    onClick={() => setShowDeleteConfirm(!showDeleteConfirm)}
                    className={`px-4 py-4 rounded-xl font-bold transition-all ${showDeleteConfirm ? 'bg-red-600 text-white animate-pulse' : 'bg-white/5 text-red-500 border border-red-500/20 hover:bg-red-500/10'}`}
                >
                    {showDeleteConfirm ? <div onClick={handleDelete} className="flex items-center gap-2"><Trash2 className="h-5 w-5" /> Borrar</div> : <Trash2 className="h-5 w-5" />}
                </button>
            )}
          </div>

        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Play, Plus, ThumbsUp, Check, Star, Users, Pencil, FileText, X, ExternalLink, Maximize2, Volume2, Pause, SkipForward, SkipBack } from 'lucide-react';
import { Movie } from '../types';

interface PlayerProps {
  movie: Movie;
  allMovies: Movie[];
  onBack: () => void;
  onMovieClick: (movie: Movie) => void;
  isLiked: boolean;
  isInMyList: boolean;
  onToggleLike: () => void;
  onToggleMyList: () => void;
  isAdmin?: boolean;
  onEdit?: (movie: Movie) => void;
}

export const Player: React.FC<PlayerProps> = ({ 
  movie, 
  onBack, 
  isLiked, 
  isInMyList, 
  onToggleLike, 
  onToggleMyList,
  isAdmin,
  onEdit
}) => {
  const [isCinemaMode, setIsCinemaMode] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [showControls, setShowControls] = useState(true);
  const videoRef = useRef<HTMLVideoElement>(null);
  const controlsTimeoutRef = useRef<number | null>(null);

  // Determine if we should use native player or iframe
  const isDirect = movie.isDirectLink || movie.streamUrl?.toLowerCase().endsWith('.mp4') || movie.streamUrl?.toLowerCase().endsWith('.mkv');

  useEffect(() => {
    setIsLoading(true);
    setIsCinemaMode(false);
  }, [movie.id]);

  const handleMouseMove = () => {
    setShowControls(true);
    if (controlsTimeoutRef.current) window.clearTimeout(controlsTimeoutRef.current);
    controlsTimeoutRef.current = window.setTimeout(() => setShowControls(false), 3000);
  };

  const handlePlayClick = () => {
    if (movie.streamUrl) {
      setIsCinemaMode(true);
    }
  };

  const openInNewTab = () => {
    window.open(movie.streamUrl, '_blank', 'noopener,noreferrer');
  };

  // UI for Cinema View
  if (isCinemaMode) {
    return (
      <div 
        className="fixed inset-0 z-[200] bg-black flex flex-col animate-fade-in overflow-hidden"
        onMouseMove={handleMouseMove}
      >
        {/* Superior Toolbar */}
        <div className={`absolute top-0 left-0 right-0 p-4 md:p-6 flex justify-between items-center z-50 bg-gradient-to-b from-black/95 via-black/60 to-transparent transition-opacity duration-500 ${showControls ? 'opacity-100' : 'opacity-0'}`}>
           <div className="flex items-center gap-4">
              <button onClick={() => setIsCinemaMode(false)} className="p-3 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full text-white transition-all"><ArrowLeft className="h-6 w-6" /></button>
              <h2 className="text-white font-black text-lg md:text-2xl tracking-tighter uppercase italic">{movie.title}</h2>
           </div>
           <div className="flex items-center gap-3">
              <button onClick={openInNewTab} className="flex items-center gap-2 px-5 py-2.5 bg-white/10 hover:bg-brand-500 rounded-full text-xs font-black text-white transition-all border border-white/10 uppercase tracking-widest"><ExternalLink className="h-4 w-4" /> Link Externo</button>
              <button onClick={() => setIsCinemaMode(false)} className="p-3 bg-red-600/20 hover:bg-red-600 rounded-full text-white transition-all"><X className="h-6 w-6" /></button>
           </div>
        </div>

        {/* Player Area */}
        <div className="flex-1 w-full h-full relative bg-[#020202] flex items-center justify-center">
            {isLoading && (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-center p-6 z-10 bg-black">
                    <div className="w-16 h-16 border-4 border-brand-500/20 border-t-brand-500 rounded-full animate-spin mb-4" />
                    <p className="text-white font-black tracking-widest uppercase text-sm animate-pulse">Sintonizando señal...</p>
                </div>
            )}

            {isDirect ? (
                /* NATIVE PREMIUM PLAYER */
                <div className="relative w-full h-full group/video">
                    <video 
                        ref={videoRef}
                        src={movie.streamUrl}
                        className="w-full h-full"
                        autoPlay
                        controls={showControls}
                        onLoadStart={() => setIsLoading(true)}
                        onCanPlay={() => setIsLoading(false)}
                    />
                    {/* Professional Overlay Controls would go here if we used a custom UI, but default controls work best for mobile/desktop for now */}
                </div>
            ) : (
                /* THIRD PARTY IFRAME */
                <iframe 
                    src={movie.streamUrl}
                    className="w-full h-full border-none"
                    allow="autoplay; fullscreen; picture-in-picture; encrypted-media; gyroscope; accelerometer"
                    title={movie.title}
                    allowFullScreen
                    onLoad={() => setIsLoading(false)}
                />
            )}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-white overflow-y-auto pb-20 font-sans">

      {/* Back Button Overlay */}
      <div className="fixed top-0 left-0 right-0 z-50 p-6 pointer-events-none flex justify-between items-start">
          <button 
            onClick={onBack}
            className="pointer-events-auto flex items-center justify-center bg-black/40 backdrop-blur-xl hover:bg-white/10 text-white transition-all rounded-full p-3 group border border-white/5"
          >
            <ArrowLeft className="h-6 w-6" />
          </button>

          {isAdmin && onEdit && (
              <button 
                onClick={() => onEdit(movie)}
                className="pointer-events-auto flex items-center justify-center bg-brand-500 hover:bg-red-600 text-white transition-all rounded-full p-3 shadow-lg"
              >
                <Pencil className="h-5 w-5 fill-white" />
              </button>
          )}
      </div>

      {/* Hero Content */}
