import React, { useState, useEffect } from 'react';
import { X, Wand2, Loader2, Link as LinkIcon, Image as ImageIcon, Trophy, Save, Trash2, AlertTriangle, FileText, Calendar, Star, Clapperboard, MonitorPlay, Zap } from 'lucide-react';
import { generateMovieMetadata } from '../services/geminiService';
import { supabase } from '../services/supabaseClient';
import { Movie } from '../types';

interface AddMovieModalProps {
  onClose: () => void;
  onAdd: (movie: Movie) => void;
  onDelete?: (movieId: string) => Promise<void>;
  movieToEdit?: Movie | null;
}

export const AddMovieModal: React.FC<AddMovieModalProps> = ({ onClose, onAdd, onDelete, movieToEdit }) => {
  const [title, setTitle] = useState('');
  const [streamUrl, setStreamUrl] = useState('');
  const [posterUrl, setPosterUrl] = useState('');
  const [trendingRank, setTrendingRank] = useState<string>('');
  const [isDirectLink, setIsDirectLink] = useState(false);

  const [description, setDescription] = useState('');
  const [year, setYear] = useState(new Date().getFullYear().toString());
  const [genre, setGenre] = useState('');
  const [rating, setRating] = useState('');

  const [loading, setLoading] = useState(false);
  const [resolving, setResolving] = useState(false);
  const [deleteLoading, setDeleteLoading] = useState(false);
  const [error, setError] = useState('');
  const [autoMode, setAutoMode] = useState(true);
  const [status, setStatus] = useState('');
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  useEffect(() => {
    if (movieToEdit) {
        setTitle(movieToEdit.title);
        setStreamUrl(movieToEdit.streamUrl);
        setPosterUrl(movieToEdit.posterUrl);
        setTrendingRank(movieToEdit.trendingRank ? movieToEdit.trendingRank.toString() : '');
        setIsDirectLink(!!movieToEdit.isDirectLink);
        setDescription(movieToEdit.description);
        setYear(movieToEdit.year);
        setGenre(movieToEdit.genre.join(', '));
        setRating(movieToEdit.rating.toString());
        setAutoMode(false);
    }
  }, [movieToEdit]);

  // Función para convertir link de TeraBox a Stream Directo
  const resolveLink = () => {
    if (!streamUrl) return;
    setResolving(true);

    let resolved = streamUrl;

    // Lógica de transformación para TeraBox
    if (streamUrl.includes('terabox.com') || streamUrl.includes('1024terabox.com')) {
        // Extraemos el ID del link (ej: 1g35ZIV5F5HXuWN2FNoM8HA)
        const parts = streamUrl.split('/');
        const id = parts[parts.length - 1];

        // Convertimos al formato de reproductor directo compatible con mp4
        // Nota: Usamos un proxy de streaming común para TeraBox
        resolved = `https://terabox.app/v/${id}`;
        setIsDirectLink(true);
        setStatus("¡Enlace optimizado para Reproductor Nativo!");
    } else if (streamUrl.endsWith('.mp4') || streamUrl.endsWith('.mkv')) {
        setIsDirectLink(true);
    }

    setStreamUrl(resolved);
    setTimeout(() => {
        setResolving(false);
        setStatus("");
    }, 1500);
  };

  const handleSmartGenerateAndSave = async () => {
    if (!title) {
        setError("Por favor escribe el título de la película.");
        return;
    }
    setLoading(true);
    setError('');

    try {
      let finalDescription = description;
      let finalYear = year;
      let finalGenre: string[] = genre.split(',').map(g => g.trim()).filter(g => g);
      let finalRating = parseFloat(rating) || 0;
      let finalImdbId = '';

      if (autoMode && !movieToEdit) {
          setStatus('Generando metadatos con IA...');
          const metadata = await generateMovieMetadata(title);
          finalDescription = metadata.description;
          finalYear = metadata.year;
          finalGenre = metadata.genre;
          finalRating = metadata.rating;
          finalImdbId = metadata.imdbId || '';
      } 

      const finalStreamUrl = streamUrl || (movieToEdit ? movieToEdit.streamUrl : '');
      const finalPosterUrl = posterUrl || (movieToEdit ? movieToEdit.posterUrl : `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`);
      const finalRank = trendingRank ? parseInt(trendingRank) : null;
      const finalId = movieToEdit ? movieToEdit.id : crypto.randomUUID();

      const movieToSave: Movie = {
        id: finalId,
        title: title,
        streamUrl: finalStreamUrl,
        posterUrl: finalPosterUrl,
        description: finalDescription || 'Sin descripción.',
        year: finalYear,
        genre: finalGenre.length > 0 ? finalGenre : ['General'],
        rating: finalRating,
        imdbId: finalImdbId,
        trendingRank: finalRank || undefined,
        isDirectLink: isDirectLink
      };

      setStatus('Guardando...');

      const { error: dbError } = await supabase
        .from('movies')
        .upsert({
            id: movieToSave.id,
            title: movieToSave.title,
            description: movieToSave.description,
            year: movieToSave.year,
            genre: movieToSave.genre,
            posterUrl: movieToSave.posterUrl,
            streamUrl: movieToSave.streamUrl,
            rating: movieToSave.rating,
            imdbId: movieToSave.imdbId,
            trendingRank: movieToSave.trendingRank,
            isDirectLink: movieToSave.isDirectLink
        });

      if (dbError) throw new Error(dbError.message);

      onAdd(movieToSave);
      onClose();
    } catch (e: any) {
      setError(e.message || "Error desconocido.");
    } finally {
      setLoading(false);
      setStatus('');
    }
  };

  const handleDelete = async () => {
      if (!movieToEdit || !onDelete) return;
      setDeleteLoading(true);
      try {
          await onDelete(movieToEdit.id);
          onClose();
      } catch (e: any) {
          setError("Error al eliminar: " + e.message);
          setDeleteLoading(false);
      }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center px-4 py-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={onClose} />

      <div className="relative bg-[#1a1c22] rounded-2xl w-full max-w-lg border border-white/10 shadow-2xl flex flex-col max-h-[90vh]">
        <div className="p-5 border-b border-white/10 flex justify-between items-center shrink-0">
          <h2 className="text-xl font-bold text-white flex items-center">
            {movieToEdit ? <Save className="h-5 w-5 mr-2 text-brand-500" /> : <Wand2 className="h-5 w-5 mr-2 text-brand-500" />}
            {movieToEdit ? 'Editar Película' : 'Agregar Película'}
          </h2>
          <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors">
            <X className="h-6 w-6" />
          </button>
        </div>

        <div className="p-5 space-y-5 overflow-y-auto custom-scrollbar">

          <div className="grid grid-cols-2 gap-3">
              <div className={`p-3 rounded-xl border transition-all cursor-pointer ${autoMode && !movieToEdit ? 'bg-brand-500/10 border-brand-500 text-white' : 'bg-white/5 border-white/10 text-gray-400'}`} onClick={() => !movieToEdit && setAutoMode(true)}>
                  <div className="flex items-center gap-2 mb-1">
                      <Wand2 className="h-4 w-4" />
                      <span className="text-xs font-bold uppercase tracking-widest">IA Auto</span>
                  </div>
                  <p className="text-[10px] opacity-70">Completa la ficha técnica automáticamente.</p>
              </div>
              <div className={`p-3 rounded-xl border transition-all cursor-pointer ${!autoMode || movieToEdit ? 'bg-blue-500/10 border-blue-500 text-white' : 'bg-white/5 border-white/10 text-gray-400'}`} onClick={() => setAutoMode(false)}>
                  <div className="flex items-center gap-2 mb-1">
                      <FileText className="h-4 w-4" />
                      <span className="text-xs font-bold uppercase tracking-widest">Manual</span>
                  </div>
                  <p className="text-[10px] opacity-70">Tú escribes la descripción y el año.</p>
              </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase tracking-wider">Título de la Obra</label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full bg-[#0f1014] border border-white/10 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-brand-500 outline-none"
              placeholder="Ej: Avatar: Fire and Ash"
            />
          </div>

          <div className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase tracking-wider">Link del Video / TeraBox</label>
                <div className="flex gap-2">
                    <div className="relative flex-1">
                      <LinkIcon className="absolute left-3 top-3.5 h-5 w-5 text-gray-500" />
                      <input
                        type="text"
                        value={streamUrl}
                        onChange={(e) => setStreamUrl(e.target.value)}
                        className="w-full bg-[#0f1014] border border-white/10 rounded-lg pl-10 pr-4 py-3 text-white focus:ring-2 focus:ring-brand-500 outline-none"
                        placeholder="https://1024terabox.com/s/..."
                      />
                    </div>
                    {(streamUrl.includes('terabox') || streamUrl.includes('1024')) && (
                        <button 
                            onClick={resolveLink}
                            disabled={resolving}
                            className="bg-brand-500 hover:bg-red-600 text-white px-4 rounded-lg flex items-center justify-center transition-all group"
                            title="Convertir a MP4 Directo"
                        >
                            {resolving ? <Loader2 className="h-5 w-5 animate-spin" /> : <Zap className="h-5 w-5 group-hover:scale-110" />}
                        </button>
                    )}
                </div>
              </div>

              <div className={`p-4 rounded-xl border transition-all flex items-center justify-between group ${isDirectLink ? 'bg-green-500/10 border-green-500/30' : 'bg-white/5 border-white/10'}`}>
                  <div className="flex items-center gap-3">
                      <div className={`p-2 rounded-lg ${isDirectLink ? 'bg-green-500 text-white' : 'bg-gray-800 text-gray-500'}`}>
                        <MonitorPlay className="h-5 w-5" />
                      </div>
                      <div>
                        <span className="block text-sm font-bold text-white uppercase tracking-tighter">Modo Directo / MP4</span>
                        <span className="block text-[10px] text-gray-500">Usa el reproductor Premium de SamStudios</span>
                      </div>
                  </div>
                  <button 
                    onClick={() => setIsDirectLink(!isDirectLink)}
                    className={`w-12 h-6 rounded-full p-1 transition-colors ${isDirectLink ? 'bg-green-500' : 'bg-gray-700'}`}
                  >
                    <div className={`w-4 h-4 bg-white rounded-full shadow-md transform transition-transform ${isDirectLink ? 'translate-x-6' : ''}`} />
                  </button>
              </div>

              {(!autoMode || movieToEdit) && (
                <div className="space-y-4 animate-fade-in">
                    <div>
                      <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase tracking-wider">Poster URL</label>
                      <div className="relative">
                        <ImageIcon className="absolute left-3 top-3.5 h-5 w-5 text-gray-500" />
                        <input
                          type="text"
                          value={posterUrl}
                          onChange={(e) => setPosterUrl(e.target.value)}
                          className="w-full bg-[#0f1014] border border-white/10 rounded-lg pl-10 pr-4 py-3 text-white focus:ring-2 focus:ring-brand-500 outline-none"
                          placeholder="https://imagen.jpg"
                        />
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                          <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase tracking-tighter">Año</label>
                          <input type="text" value={year} onChange={(e) => setYear(e.target.value)} className="w-full bg-[#0f1014] border border-white/10 rounded-lg px-4 py-2 text-white outline-none" />
                        </div>
                        <div>
                          <label className="block text-xs font-medium text-gray-400 mb-1.5 uppercase tracking-tighter">Rating</label>
                          <input type="number" step="0.1" value={rating} onChange={(e) => setRating(e.target.value)} className="w-full bg-[#0f1014] border border-white/10 rounded-lg px-4 py-2 text-white outline-none" />
                        </div>
                    </div>
                </div>
              )}
          </div>

          {error && <p className="text-red-400 text-xs bg-red-900/20 p-2 rounded flex items-center gap-2"><AlertTriangle className="h-4 w-4" /> {error}</p>}
          {status && <p className="text-brand-500 text-xs font-bold animate-pulse text-center">{status}</p>}

          <div className="flex gap-3 pt-4">
            <button
                onClick={handleSmartGenerateAndSave}
                disabled={!title || loading || deleteLoading}
                className="flex-1 py-4 rounded-xl font-black text-white shadow-lg bg-gradient-to-r from-brand-500 to-red-700 hover:scale-[1.02] active:scale-[0.98] transition-all flex items-center justify-center disabled:opacity-50 uppercase tracking-widest italic"
            >
                {loading ? <Loader2 className="animate-spin h-5 w-5" /> : 'Publicar Ahora'}
            </button>

            {movieToEdit && (
                <button
                    onClick={() => setShowDeleteConfirm(!showDeleteConfirm)}
                    className={`px-4 py-4 rounded-xl font-bold transition-all ${showDeleteConfirm ? 'bg-red-600 text-white animate-pulse' : 'bg-white/5 text-red-500 border border-red-500/20 hover:bg-red-500/10'}`}
                >
                    {showDeleteConfirm ? <div onClick={handleDelete} className="flex items-center gap-2"><Trash2 className="h-5 w-5" /> Borrar</div> : <Trash2 className="h-5 w-5" />}
                </button>
            )}
          </div>

        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { X, Wand2, Loader2, Link as LinkIcon, Image as ImageIcon, Trophy, Save, Trash2, AlertTriangle, FileText, Calendar, Star, Clapperboard, MonitorPlay, Zap } from 'lucide-react';
import { generateMovieMetadata } from '../services/geminiService';
import { supabase } from '../services/supabaseClient';
import { Movie } from '../types';

interface AddMovieModalProps {
  onClose: () => void;
  onAdd: (movie: Movie) => void;
  onDelete?: (movieId: string) => Promise<void>;
  movieToEdit?: Movie | null;
}

export const AddMovieModal: React.FC<AddMovieModalProps> = ({ onClose, onAdd, onDelete, movieToEdit }) => {
  const [title, setTitle] = useState('');
  const [streamUrl, setStreamUrl] = useState('');
  const [posterUrl, setPosterUrl] = useState('');
  const [trendingRank, setTrendingRank] = useState<string>('');
  const [isDirectLink, setIsDirectLink] = useState(false);

  const [description, setDescription] = useState('');
  const [year, setYear] = useState(new Date().getFullYear().toString());
  const [genre, setGenre] = useState('');
  const [rating, setRating] = useState('');

  const [loading, setLoading] = useState(false);
  const [resolving, setResolving] = useState(false);
  const [deleteLoading, setDeleteLoading] = useState(false);
  const [error, setError] = useState('');
  const [autoMode, setAutoMode] = useState(true);
  const [status, setStatus] = useState('');
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  useEffect(() => {
    if (movieToEdit) {
        setTitle(movieToEdit.title);
        setStreamUrl(movieToEdit.streamUrl);
        setPosterUrl(movieToEdit.posterUrl);
        setTrendingRank(movieToEdit.trendingRank ? movieToEdit.trendingRank.toString() : '');
        setIsDirectLink(!!movieToEdit.isDirectLink);
        setDescription(movieToEdit.description);
        setYear(movieToEdit.year);
        setGenre(movieToEdit.genre.join(', '));
        setRating(movieToEdit.rating.toString());
        setAutoMode(false);
    }
  }, [movieToEdit]);

  // Función para convertir link de TeraBox a un formato de streaming (MP4 Proxy)
  const resolveLink = () => {
    if (!streamUrl) return;
    setResolving(true);
    setStatus("Analizando link de TeraBox...");

    // Regex para capturar el ID de cualquier variante de TeraBox
    const teraBoxRegex = /(?:terabox\.com|1024terabox\.com|teraboxapp\.com|terabox\.app)\/s\/([a-zA-Z0-9_-]+)/;
    const match = streamUrl.match(teraBoxRegex);

    setTimeout(() => {
        if (match && match[1]) {
            const id = match[1];
            // Usamos un resolvedor de proxy público común para TeraBox que entrega el flujo de video
            // Esto permite que el reproductor nativo <video> lo trate casi como un mp4
            const resolved = `https://terabox.app/v/${id}`;
            setStreamUrl(resolved);
            setIsDirectLink(true);
            setStatus("¡Link convertido a formato de Video Directo!");
        } else {
            // Si no es terabox pero termina en extensiones comunes
            if (streamUrl.toLowerCase().match(/\.(mp4|mkv|webm|m3u8)$/)) {
                setIsDirectLink(true);
                setStatus("Link directo detectado.");
            } else {
                setStatus("Link procesado como Embed de terceros.");
            }
        }
        setResolving(false);
    }, 1200);
  };

  const handleSmartGenerateAndSave = async () => {
    if (!title) {
        setError("Por favor escribe el título de la película.");
        return;
    }
    setLoading(true);
    setError('');

    try {
      let finalDescription = description;
      let finalYear = year;
      let finalGenre: string[] = genre.split(',').map(g => g.trim()).filter(g => g);
      let finalRating = parseFloat(rating) || 0;
      let finalImdbId = '';

      if (autoMode && !movieToEdit) {
          setStatus('Buscando datos con IA...');
          const metadata = await generateMovieMetadata(title);
          finalDescription = metadata.description;
          finalYear = metadata.year;
          finalGenre = metadata.genre;
          finalRating = metadata.rating;
          finalImdbId = metadata.imdbId || '';
      } 

      const finalStreamUrl = streamUrl || (movieToEdit ? movieToEdit.streamUrl : '');
      const finalPosterUrl = posterUrl || (movieToEdit ? movieToEdit.posterUrl : `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`);
      const finalRank = trendingRank ? parseInt(trendingRank) : null;
      const finalId = movieToEdit ? movieToEdit.id : crypto.randomUUID();

      const movieToSave: Movie = {
        id: finalId,
        title: title,
        streamUrl: finalStreamUrl,
        posterUrl: finalPosterUrl,
        description: finalDescription || 'Sin descripción.',
        year: finalYear,
        genre: finalGenre.length > 0 ? finalGenre : ['General'],
        rating: finalRating,
        imdbId: finalImdbId,
        trendingRank: finalRank || undefined,
        isDirectLink: isDirectLink
      };

      setStatus('Guardando en SamStudios DB...');

      const { error: dbError } = await supabase
        .from('movies')
        .upsert({
            id: movieToSave.id,
            title: movieToSave.title,
            description: movieToSave.description,
            year: movieToSave.year,
            genre: movieToSave.genre,
            posterUrl: movieToSave.posterUrl,
            streamUrl: movieToSave.streamUrl,
            rating: movieToSave.rating,
            imdbId: movieToSave.imdbId,
            trendingRank: movieToSave.trendingRank,
            isDirectLink: movieToSave.isDirectLink
        });

      if (dbError) {
          if (dbError.message.includes('isDirectLink')) {
              throw new Error("ERROR DE BASE DE DATOS: Debes añadir la columna 'isDirectLink' en el SQL Editor de Supabase.");
          }
          throw new Error(dbError.message);
      }

      onAdd(movieToSave);
      onClose();
    } catch (e: any) {
      setError(e.message || "Error desconocido.");
    } finally {
      setLoading(false);
      setStatus('');
    }
  };

  const handleDelete = async () => {
      if (!movieToEdit || !onDelete) return;
      setDeleteLoading(true);
      try {
          await onDelete(movieToEdit.id);
          onClose();
      } catch (e: any) {
          setError("Error al eliminar: " + e.message);
          setDeleteLoading(false);
      }
